UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Calcul de limites (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Substitution, formes 0/0, infini.","exercices":[{"number":1,"title_fr":"Calculs directs","points":5,"preamble_fr":"Calculer les limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 1} (x^2 + 2x - 3)$.","points":1,"solution":{"steps":[{"text_fr":"Polynôme continu → substitution : $1 + 2 - 3 = 0$."}],"final_answer_fr":"$0$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 1} (x^2 - 1)/(x - 1)$.","points":2,"solution":{"steps":[{"text_fr":"Forme 0/0. $(x-1)(x+1)/(x-1) = x + 1 \\to 2$."}],"final_answer_fr":"$2$"}},{"number":3,"stem_fr":"$\\lim_{x \\to +\\infty} (3x^2 + 1)/(x^2 + x)$.","points":2,"solution":{"steps":[{"text_fr":"Quotient même degré → coeffs dominants : $3/1 = 3$."}],"final_answer_fr":"$3$"}}]},{"number":2,"title_fr":"Croissances comparées","points":5,"preamble_fr":"Calculer ces limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to +\\infty} \\ln x / x$.","points":2,"solution":{"steps":[{"text_fr":"Croissances comparées : $\\ln x \\ll x$ à l''infini, limite = 0."}],"final_answer_fr":"$0$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty} e^x / x$.","points":2,"solution":{"steps":[{"text_fr":"Exponentielle l''emporte sur toute puissance : limite = $+\\infty$."}],"final_answer_fr":"$+\\infty$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 0^+} x \\ln x$.","points":1,"solution":{"steps":[{"text_fr":"Forme $0 \\cdot (-\\infty)$. Limite usuelle = 0."}],"final_answer_fr":"$0$"}}]},{"number":3,"title_fr":"Limites latérales","points":5,"preamble_fr":"Soit $f(x) = 1/x$.","questions":[{"number":1,"stem_fr":"$\\lim_{0^+} f$ et $\\lim_{0^-} f$.","points":3,"solution":{"steps":[{"text_fr":"$0^+$ : $x > 0$ petit → $1/x \\to +\\infty$. $0^-$ : $x < 0$ petit → $1/x \\to -\\infty$."}],"final_answer_fr":"$\\pm\\infty$"}},{"number":2,"stem_fr":"Asymptotes de $f$ ?","poin