UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Dérivation et applications (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Calcul de dérivées, variations, applications.","exercices":[{"number":1,"title_fr":"Dérivées","points":5,"preamble_fr":"Calculer.","questions":[{"number":1,"stem_fr":"$f(x) = 3x^2 - 5x + 2$.","points":1,"solution":{"steps":[{"text_fr":"$f''(x) = 6x - 5$."}],"final_answer_fr":"$6x - 5$"}},{"number":2,"stem_fr":"$g(x) = (x+1)(x-3)$.","points":2,"solution":{"steps":[{"text_fr":"Produit : $g'' = 1 \\cdot (x-3) + (x+1) \\cdot 1 = 2x - 2$."}],"final_answer_fr":"$2x - 2$"}},{"number":3,"stem_fr":"$h(x) = e^x/x$ sur $\\mathbb{R}^*$.","points":2,"solution":{"steps":[{"text_fr":"Quotient : $h'' = (e^x \\cdot x - e^x \\cdot 1)/x^2 = e^x (x-1)/x^2$."}],"final_answer_fr":"$e^x (x-1)/x^2$"}}]},{"number":2,"title_fr":"Variations","points":5,"preamble_fr":"$f(x) = x^3 - 3x + 2$ sur $\\mathbb{R}$.","questions":[{"number":1,"stem_fr":"Calculer $f''$ et étudier son signe.","points":3,"solution":{"steps":[{"text_fr":"$f''(x) = 3x^2 - 3 = 3(x-1)(x+1)$. Signe $+$ sur $]-\\infty, -1[$, $-$ sur $]-1, 1[$, $+$ sur $]1, +\\infty[$."}],"final_answer_fr":"Croît, décroît, croît"}},{"number":2,"stem_fr":"Extrema locaux.","points":2,"solution":{"steps":[{"text_fr":"Max local $f(-1) = 4$. Min local $f(1) = 0$."}],"final_answer_fr":"Max 4, min 0"}}]},{"number":3,"title_fr":"Tangente","points":5,"preamble_fr":"Soit $f(x) = x^2 + 1$.","questions":[{"number":1,"stem_fr":"Équation de la tangente en $x_0 = 2$.","points":3,"solution":{"steps":[{"text_fr":"$f(2) = 5$, $f''(x) = 2x$, $f''(2) = 4$."},{"text_fr":"$T : y = 4(x - 2) + 5 = 4x - 3$."}],"final_answer_fr":"$y = 4x - 3$"}},{"number":2,"stem_fr":"Tangente horizontale ?","points":2,"solution":{"steps":[{"text_fr":"$f''(x) = 0 \\iff x = 0$. $f(0) = 1$. Point : $(0, 1)$."}],"final_answer_fr":"$(0, 1)$"}}]},{"number":4,"title_fr":"Optimisation","points":5,"preamble_fr":"Une boîte ouverte sur le dessus a un carré de côté $x$ comme base et hauteur $10 - x$. Volume $V(x) = x^2 (10 - x)$.","questions":[{"number":1,"stem_fr":"Domaine et $V''(x)$.","points":3,"solution":{"steps":[{"text_fr":"Domaine : $0 < x < 10$."},{"text_fr":"$V'' = 2x(10-x) + x^2 \\cdot (-1) = 20x - 3x^2 = x(20 - 3x)$."}],"final_answer_fr":"$V'' = x(20 - 3x)$"}},{"number":2,"stem_fr":"Volume maximal.","points":2,"solution":{"steps":[{"text_fr":"$V'' = 0 \\iff x = 0$ ou $x = 20/3 \\approx 6{,}67$."},{"text_fr":"$V(20/3) = (400/9)(10/3) = 4000/27 \\approx 148\\,\\text{cm}^3$."}],"final_answer_fr":"$\\approx 148$ cm³"}}]}]}'::jsonb WHERE code = 'svt_deriv_apps';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Exponentielle et logarithme (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Propriétés algébriques, équations, applications.","exercices":[{"number":1,"title_fr":"Calculs","points":5,"preamble_fr":"Simplifier ou résoudre.","questions":[{"number":1,"stem_fr":"$\\ln 4 - \\ln 2$.","points":1,"solution":{"steps":[{"text_fr":"$\\ln(4/2) = \\ln 2$."}],"final_answer_fr":"$\\ln 2$"}},{"number":2,"stem_fr":"$e^{\\ln 5}$.","points":1,"solution":{"steps":[{"text_fr":"$e^{\\ln x} = x$ → résultat = 5."}],"final_answer_fr":"$5$"}},{"number":3,"stem_fr":"Résoudre $e^x = 3$.","points":2,"solution":{"steps":[{"text_fr":"$x = \\ln 3 \\approx 1{,}099$."}],"final_answer_fr":"$x = \\ln 3$"}},{"number":4,"stem_fr":"Résoudre $\\ln(x - 1) = 0$.","points":1,"solution":{"steps":[{"text_fr":"$x - 1 = e^0 = 1 \\iff x = 2$ (avec $x > 1$ ✓)."}],"final_answer_fr":"$x = 2$"}}]},{"number":2,"title_fr":"Étude de $f(x) = x e^{-x}$","points":5,"preamble_fr":"Sur $\\mathbb{R}$.","questions":[{"number":1,"stem_fr":"$f''(x)$.","points":2,"solution":{"steps":[{"text_fr":"$f'' = e^{-x} - x e^{-x} = (1 - x) e^{-x}$."}],"final_answer_fr":"$(1-x) e^{-x}$"}},{"number":2,"stem_fr":"Variations et extremum.","points":2,"solution":{"steps":[{"text_fr":"$e^{-x} > 0$ → signe = signe de $(1-x)$. Max en $x = 1$, $f(1) = 1/e \\approx 0{,}37$."}],"final_answer_fr":"Max $1/e$ en $x=1$"}},{"number":3,"stem_fr":"$\\lim_{+\\infty} f$ ?","points":1,"solution":{"steps":[{"text_fr":"$x/e^x \\to 0$ par croissances comparées."}],"final_answer_fr":"$0$"}}]},{"number":3,"title_fr":"Décroissance radioactive","points":5,"preamble_fr":"$N(t) = N_0 e^{-\\lambda t}$ avec $\\lambda = 0{,}1\\,\\text{an}^{-1}$.","questions":[{"number":1,"stem_fr":"Demi-vie.","points":2,"solution":{"steps":[{"text_fr":"$t_{1/2} = \\ln 2 / \\lambda = 0{,}693/0{,}1 \\approx 6{,}93\\,\\text{ans}$."}],"final_answer_fr":"$\\approx 6{,}93$ ans"}},{"number":2,"stem_fr":"Temps pour 99% de disparition.","points":3,"solution":{"steps":[{"text_fr":"$N/N_0 = 0{,}01 \\iff t = \\ln 100/\\lambda = 4{,}605/0{,}1 \\approx 46\\,\\text{ans}$."}],"final_answer_fr":"$\\approx 46$ ans"}}]},{"number":4,"title_fr":"Équation $e^{2x} - e^x - 6 = 0$","points":5,"preamble_fr":"Résoudre dans $\\mathbb{R}$.","questions":[{"number":1,"stem_fr":"Poser $X = e^x$.","points":2,"solution":{"steps":[{"text_fr":"$X > 0$. Équation : $X^2 - X - 6 = 0$."}],"final_answer_fr":"$X^2 - X - 6 = 0$"}},{"number":2,"stem_fr":"Résoudre.","points":3,"solution":{"steps":[{"text_fr":"$\\Delta = 1 + 24 = 25$. $X = (1 \\pm 5)/2 = 3$ ou $-2$ (exclu)."},{"text_fr":"$e^x = 3 \\iff x = \\ln 3$."}],"final_answer_fr":"$x = \\ln 3$"}}]}]}'::jsonb WHERE code = 'svt_exp_ln_combined';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Primitives et intégrales (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Primitives, calcul d''intégrales, aires.","exercices":[{"number":1,"title_fr":"Primitives","points":5,"preamble_fr":"Donner une primitive.","questions":[{"number":1,"stem_fr":"$f(x) = 3 x^2 - 2x + 1$.","points":1,"solution":{"steps":[{"text_fr":"$F(x) = x^3 - x^2 + x + C$."}],"final_answer_fr":"$x^3 - x^2 + x + C$"}},{"number":2,"stem_fr":"$g(x) = e^{2x}$.","points":1,"solution":{"steps":[{"text_fr":"$G(x) = e^{2x}/2 + C$."}],"final_answer_fr":"$e^{2x}/2 + C$"}},{"number":3,"stem_fr":"$h(x) = 1/x$ sur $]0, +\\infty[$.","points":1,"solution":{"steps":[{"text_fr":"$H(x) = \\ln x + C$."}],"final_answer_fr":"$\\ln x + C$"}},{"number":4,"stem_fr":"$k(x) = 2x/(x^2 + 1)$.","points":2,"solution":{"steps":[{"text_fr":"Forme $u''/u$ avec $u = x^2 + 1$. $K(x) = \\ln(x^2 + 1) + C$."}],"final_answer_fr":"$\\ln(x^2+1) + C$"}}]},{"number":2,"title_fr":"Intégrales","points":5,"preamble_fr":"Calculer.","questions":[{"number":1,"stem_fr":"$\\int_0^2 (x^2 + 1)\\,dx$.","points":2,"solution":{"steps":[{"text_fr":"$[x^3/3 + x]_0^2 = 8/3 + 2 = 14/3$."}],"final_answer_fr":"$14/3$"}},{"number":2,"stem_fr":"$\\int_0^1 e^x\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"$[e^x]_0^1 = e - 1 \\approx 1{,}72$."}],"final_answer_fr":"$e - 1$"}},{"number":3,"stem_fr":"$\\int_1^e 1/x\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"$[\\ln x]_1^e = 1 - 0 = 1$."}],"final_answer_fr":"$1$"}},{"number":4,"stem_fr":"$\\int_0^{\\pi/2} \\sin x\\,dx$.","points":1,"solution":{"steps":[{"text_fr":"$[-\\cos x]_0^{\\pi/2} = 0 - (-1) = 1$."}],"final_answer_fr":"$1$"}}]},{"number":3,"title_fr":"Aire","points":5,"preamble_fr":"Aire sous la courbe $y = x^2$ entre 0 et 3.","questions":[{"number":1,"stem_fr":"Calcul.","points":2,"solution":{"steps":[{"text_fr":"$\\int_0^3 x^2\\,dx = [x^3/3]_0^3 = 9$ unités d''aire."}],"final_answer_fr":"$A = 9$"}},{"number":2,"stem_fr":"Aire entre $y = x^2$ et $y = x$ sur $[0, 1]$.","points":3,"solution":{"steps":[{"text_fr":"Sur $[0, 1]$, $x \\ge x^2$. Aire $= \\int_0^1 (x - x^2)\\,dx = [x^2/2 - x^3/3]_0^1 = 1/2 - 1/3 = 1/6$."}],"final_answer_fr":"$1/6$"}}]},{"number":4,"title_fr":"Application — distance","points":5,"preamble_fr":"Vitesse $v(t) = 3 t^2 + 2$ (m/s) entre $t = 0$ et $t = 4$ s.","questions":[{"number":1,"stem_fr":"Distance parcourue ?","points":3,"solution":{"steps":[{"text_fr":"Distance = $\\int_0^4 v(t)\\,dt = [t^3 + 2t]_0^4 = 64 + 8 = 72\\,\\text{m}$."}],"final_answer_fr":"$72$ m"}},{"number":2,"stem_fr":"Vitesse moyenne ?","points":2,"solution":{"steps":[{"text_fr":"$\\bar v = 72/4 = 18\\,\\text{m/s}$."}],"final_answer_fr":"$18$ m/s"}}]}]}'::jsonb WHERE code = 'svt_integral_basics';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Lois de Newton (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Applications simples des lois de Newton.","exercices":[{"number":1,"title_fr":"Équilibre","points":5,"preamble_fr":"Caisse 20 kg suspendue par une corde verticale. $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Bilan et tension.","points":3,"solution":{"steps":[{"text_fr":"Forces : poids $\\vec P$ (descendant, $P = 200\\,\\text{N}$) et tension $\\vec T$ (montante)."},{"text_fr":"Équilibre : $T = P = 200\\,\\text{N}$."}],"final_answer_fr":"$T = 200$ N"}},{"number":2,"stem_fr":"Si la corde fait un angle de 30° avec la verticale (un seul fil oblique).","points":2,"solution":{"steps":[{"text_fr":"Composante verticale de $T$ : $T \\cos 30° = P \\iff T = 200/\\cos 30° \\approx 231\\,\\text{N}$."}],"final_answer_fr":"$T \\approx 231$ N"}}]},{"number":2,"title_fr":"Chute libre","points":5,"preamble_fr":"Pierre lâchée sans vitesse initiale d''une hauteur 45 m. $g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"Durée de chute.","points":2,"solution":{"steps":[{"text_fr":"$h = (1/2) g t^2 \\iff t = \\sqrt{2 h/g} = \\sqrt{9} = 3\\,\\text{s}$."}],"final_answer_fr":"$t = 3$ s"}},{"number":2,"stem_fr":"Vitesse à l''impact.","points":2,"solution":{"steps":[{"text_fr":"$v = g t = 30\\,\\text{m/s} = 108\\,\\text{km/h}$."}],"final_answer_fr":"$v = 30$ m/s"}},{"number":3,"stem_fr":"Énergie cinétique pour $m = 2\\,\\text{kg}$.","points":1,"solution":{"steps":[{"text_fr":"$E_c = 0{,}5 \\times 2 \\times 900 = 900\\,\\text{J}$."}],"final_answer_fr":"$900$ J"}}]},{"number":3,"title_fr":"Plan incliné","points":5,"preamble_fr":"Bloc 5 kg sur plan à 30°, sans frottement. $g = 10$.","questions":[{"number":1,"stem_fr":"Accélération.","points":3,"solution":{"steps":[{"text_fr":"Projection selon le plan : $m a = m g \\sin\\alpha$, donc $a = g \\sin 30° = 5\\,\\text{m/s}^2$."}],"final_answer_fr":"$a = 5$ m/s²"}},{"number":2,"stem_fr":"Vitesse après 2 s, départ repos.","points":2,"solution":{"steps":[{"text_fr":"$v = a t = 10\\,\\text{m/s}$."}],"final_answer_fr":"$v = 10$ m/s"}}]},{"number":4,"title_fr":"Poulie idéale","points":5,"preamble_fr":"Deux blocs $m_1 = 4\\,\\text{kg}$, $m_2 = 2\\,\\text{kg}$ reliés par un fil sur une poulie.","questions":[{"number":1,"stem_fr":"Accélération et tension.","points":4,"solution":{"steps":[{"text_fr":"Bloc 1 (descend) : $m_1 g - T = m_1 a \\Rightarrow 40 - T = 4a$."},{"text_fr":"Bloc 2 (monte) : $T - m_2 g = m_2 a \\Rightarrow T - 20 = 2a$."},{"text_fr":"Somme : $20 = 6a \\Rightarrow a = 3{,}33\\,\\text{m/s}^2$. $T = 20 + 2 \\times 3{,}33 = 26{,}67\\,\\text{N}$."}],"final_answer_fr":"$a \\approx 3{,}33$ m/s², $T \\approx 26{,}67$ N"}},{"number":2,"stem_fr":"Pourquoi $T < m_1 g$ ?","points":1,"solution":{"steps":[{"text_fr":"Sinon le bloc 1 ne descendrait pas. $T$ s''oppose à la chute mais ne la compense pas entièrement."}],"final_answer_fr":"car bloc descend"}}]}]}'::jsonb WHERE code = 'svt_newton_apps';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Énergie mécanique (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Énergie cinétique, potentielle, conservation.","exercices":[{"number":1,"title_fr":"Calculs","points":5,"preamble_fr":"$g = 10\\,\\text{m/s}^2$.","questions":[{"number":1,"stem_fr":"$E_c$ d''une voiture 1000 kg à 90 km/h.","points":2,"solution":{"steps":[{"text_fr":"$v = 25\\,\\text{m/s}$. $E_c = 0{,}5 \\times 1000 \\times 625 = 312500\\,\\text{J} = 312{,}5\\,\\text{kJ}$."}],"final_answer_fr":"$312{,}5$ kJ"}},{"number":2,"stem_fr":"$E_p$ d''un objet 5 kg à 20 m.","points":1,"solution":{"steps":[{"text_fr":"$E_p = m g h = 5 \\times 10 \\times 20 = 1000\\,\\text{J}$."}],"final_answer_fr":"$1000$ J"}},{"number":3,"stem_fr":"Conversion : à quelle hauteur l''objet (5 kg) aura-t-il $E_p = 1000\\,\\text{J}$ d''$E_c$ ?","points":2,"solution":{"steps":[{"text_fr":"Conservation : $mgh = (1/2) m v^2 \\Rightarrow v = \\sqrt{2 g h} = 20\\,\\text{m/s}$."}],"final_answer_fr":"$v = 20$ m/s"}}]},{"number":2,"title_fr":"Toboggan","points":5,"preamble_fr":"Enfant 30 kg lâché du haut d''un toboggan de hauteur 3 m, sans frottement.","questions":[{"number":1,"stem_fr":"Vitesse en bas.","points":3,"solution":{"steps":[{"text_fr":"Conservation : $v = \\sqrt{2gh} = \\sqrt{60} \\approx 7{,}75\\,\\text{m/s} \\approx 28\\,\\text{km/h}$."}],"final_answer_fr":"$\\approx 7{,}75$ m/s"}},{"number":2,"stem_fr":"Avec frottement, vitesse réelle = 5 m/s. Énergie dissipée ?","points":2,"solution":{"steps":[{"text_fr":"$E_m^\\text{haut} = mgh = 900\\,\\text{J}$. $E_c^\\text{bas} = 0{,}5 \\times 30 \\times 25 = 375\\,\\text{J}$."},{"text_fr":"Dissipée : $900 - 375 = 525\\,\\text{J}$."}],"final_answer_fr":"$525$ J"}}]},{"number":3,"title_fr":"Ressort","points":5,"preamble_fr":"Ressort $k = 200\\,\\text{N/m}$, comprimé de 5 cm, libéré pour propulser une bille de 100 g.","questions":[{"number":1,"stem_fr":"Énergie potentielle élastique stockée.","points":2,"solution":{"steps":[{"text_fr":"$E_{pe} = (1/2) k x^2 = 0{,}5 \\times 200 \\times 0{,}0025 = 0{,}25\\,\\text{J}$."}],"final_answer_fr":"$0{,}25$ J"}},{"number":2,"stem_fr":"Vitesse maximale de la bille.","points":3,"solution":{"steps":[{"text_fr":"Conservation : $(1/2) m v^2 = 0{,}25 \\Rightarrow v = \\sqrt{0{,}5/0{,}1} = \\sqrt 5 \\approx 2{,}24\\,\\text{m/s}$."}],"final_answer_fr":"$\\approx 2{,}24$ m/s"}}]},{"number":4,"title_fr":"TEC avec frottement","points":5,"preamble_fr":"Caisse 20 kg tirée par F = 50 N sur 10 m, frottement 10 N.","questions":[{"number":1,"stem_fr":"Travail total et vitesse finale (départ repos).","points":4,"solution":{"steps":[{"text_fr":"$W_F = 50 \\times 10 = 500\\,\\text{J}$. $W_f = -10 \\times 10 = -100\\,\\text{J}$. $W_\\text{total} = 400\\,\\text{J}$."},{"text_fr":"TEC : $\\Delta E_c = 400 \\Rightarrow v = \\sqrt{800/20} = \\sqrt{40} \\approx 6{,}32\\,\\text{m/s}$."}],"final_answer_fr":"$v \\approx 6{,}32$ m/s"}}]}]}'::jsonb WHERE code = 'svt_energy';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Ondes (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Célérité, longueur d''onde, types d''ondes.","exercices":[{"number":1,"title_fr":"Vocabulaire et relations","points":5,"preamble_fr":"Onde sur une corde de fréquence 50 Hz, célérité 20 m/s.","questions":[{"number":1,"stem_fr":"Période $T$ et longueur d''onde $\\lambda$.","points":2,"solution":{"steps":[{"text_fr":"$T = 1/f = 20\\,\\text{ms}$. $\\lambda = v/f = 0{,}4\\,\\text{m}$."}],"final_answer_fr":"$T = 20$ ms, $\\lambda = 0{,}4$ m"}},{"number":2,"stem_fr":"Distance entre deux maxima consécutifs.","points":1,"solution":{"steps":[{"text_fr":"$= \\lambda = 0{,}4\\,\\text{m}$."}],"final_answer_fr":"$0{,}4$ m"}},{"number":3,"stem_fr":"Si f est doublée (v inchangée), comment varie $\\lambda$ ?","points":2,"solution":{"steps":[{"text_fr":"$\\lambda \\propto 1/f$ → divisée par 2. Nouvelle $\\lambda = 0{,}2\\,\\text{m}$."}],"final_answer_fr":"divisée par 2"}}]},{"number":2,"title_fr":"Son","points":5,"preamble_fr":"Vitesse du son ≈ 340 m/s dans l''air.","questions":[{"number":1,"stem_fr":"Distance d''un éclair : 3 s entre éclair et tonnerre.","points":2,"solution":{"steps":[{"text_fr":"$d = v t = 340 \\times 3 = 1020\\,\\text{m} \\approx 1\\,\\text{km}$."}],"final_answer_fr":"$\\approx 1$ km"}},{"number":2,"stem_fr":"Pourquoi entend-on le tonnerre après l''éclair ?","points":2,"solution":{"steps":[{"text_fr":"Lumière instantanée à l''échelle humaine ($c = 3 \\times 10^8\\,\\text{m/s}$), son très lent (340 m/s)."}],"final_answer_fr":"v_lumière >> v_son"}},{"number":3,"stem_fr":"Onde sonore : transversale ou longitudinale ?","points":1,"solution":{"steps":[{"text_fr":"**Longitudinale** : oscillation des molécules d''air parallèle à la propagation."}],"final_answer_fr":"longitudinale"}}]},{"number":3,"title_fr":"Lumière et spectre","points":5,"preamble_fr":"Spectre visible : 400-700 nm.","questions":[{"number":1,"stem_fr":"Fréquence d''une lumière à $\\lambda = 600\\,\\text{nm}$.","points":2,"solution":{"steps":[{"text_fr":"$f = c/\\lambda = 3 \\times 10^8 / 6 \\times 10^{-7} = 5 \\times 10^{14}\\,\\text{Hz}$."}],"final_answer_fr":"$5 \\times 10^{14}$ Hz"}},{"number":2,"stem_fr":"Couleur correspondante.","points":1,"solution":{"steps":[{"text_fr":"**Orange**. Le visible va du violet (~400 nm) au rouge (~700 nm)."}],"final_answer_fr":"orange"}},{"number":3,"stem_fr":"Plus une couleur a une longueur d''onde courte, plus son énergie est :","points":2,"solution":{"steps":[{"text_fr":"**Élevée**. $E = h f = h c/\\lambda \\propto 1/\\lambda$. Violet plus énergétique que rouge."}],"final_answer_fr":"élevée"}}]},{"number":4,"title_fr":"Diffraction","points":5,"preamble_fr":"Laser $\\lambda = 633\\,\\text{nm}$ traverse une fente $a = 0{,}2\\,\\text{mm}$, écran à $D = 2\\,\\text{m}$.","questions":[{"number":1,"stem_fr":"Demi-largeur de la tache centrale.","points":3,"solution":{"steps":[{"text_fr":"$\\theta \\approx \\lambda/a = 6{,}33 \\times 10^{-7}/2 \\times 10^{-4} = 3{,}17 \\times 10^{-3}\\,\\text{rad}$."},{"text_fr":"$\\ell = D \\theta = 2 \\times 3{,}17 \\times 10^{-3} \\approx 6{,}33\\,\\text{mm}$."}],"final_answer_fr":"$\\approx 6{,}3$ mm"}},{"number":2,"stem_fr":"Effet de réduire la fente ?","points":2,"solution":{"steps":[{"text_fr":"$\\theta \\propto 1/a$ → tache plus large. Contre-intuitif mais essentiel."}],"final_answer_fr":"tache plus large"}}]}]}'::jsonb WHERE code = 'svt_waves';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Radioactivité et datation (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Désintégrations, demi-vie, datation.","exercices":[{"number":1,"title_fr":"Désintégrations","points":5,"preamble_fr":"Écrire les équations.","questions":[{"number":1,"stem_fr":"Désintégration $\\alpha$ de $^{226}_{88}\\text{Ra}$.","points":2,"solution":{"steps":[{"text_fr":"$^{226}_{88}\\text{Ra} \\to ^{222}_{86}\\text{Rn} + ^4_2\\text{He}$ (lois de Soddy)."},{"text_fr":"Le radon-222 est produit (gaz radioactif présent dans certains sous-sols)."}],"final_answer_fr":"$\\to ^{222}_{86}Rn + ^4_2He$"}},{"number":2,"stem_fr":"Désintégration $\\beta^-$ de $^{14}_6\\text{C}$.","points":2,"solution":{"steps":[{"text_fr":"$^{14}_6\\text{C} \\to ^{14}_7\\text{N} + ^0_{-1}e$. $A$ inchangé, $Z$ augmente de 1."}],"final_answer_fr":"$\\to ^{14}_7N + e^-$"}},{"number":3,"stem_fr":"Différence entre $\\alpha$ et $\\gamma$.","points":1,"solution":{"steps":[{"text_fr":"$\\alpha$ = particule matérielle (noyau He), perte de masse. $\\gamma$ = photon (rayonnement EM), pas de perte de masse, juste désexcitation."}],"final_answer_fr":"$\\alpha$ massive, $\\gamma$ photon"}}]},{"number":2,"title_fr":"Loi de décroissance","points":5,"preamble_fr":"Source de $10^{10}$ noyaux, demi-vie 4 jours.","questions":[{"number":1,"stem_fr":"Constante $\\lambda$.","points":1,"solution":{"steps":[{"text_fr":"$\\lambda = \\ln 2/4 \\approx 0{,}173\\,\\text{jour}^{-1}$."}],"final_answer_fr":"$\\approx 0{,}173$ /jour"}},{"number":2,"stem_fr":"Noyaux restants après 12 jours.","points":2,"solution":{"steps":[{"text_fr":"$12 = 3 \\times t_{1/2}$ → $N = N_0/2^3 = 10^{10}/8 = 1{,}25 \\times 10^9$."}],"final_answer_fr":"$1{,}25 \\times 10^9$"}},{"number":3,"stem_fr":"Activité initiale en Bq.","points":2,"solution":{"steps":[{"text_fr":"Convertir $\\lambda$ en $\\text{s}^{-1}$ : $0{,}173/86400 \\approx 2 \\times 10^{-6}\\,\\text{s}^{-1}$."},{"text_fr":"$A_0 = \\lambda N_0 = 2 \\times 10^{-6} \\times 10^{10} = 2 \\times 10^4\\,\\text{Bq} = 20\\,\\text{kBq}$."}],"final_answer_fr":"$\\approx 20$ kBq"}}]},{"number":3,"title_fr":"Datation au C14","points":5,"preamble_fr":"Demi-vie = 5730 ans. Activité initiale 13,6 Bq/g de carbone.","questions":[{"number":1,"stem_fr":"Échantillon archéologique à 3,4 Bq/g. Âge ?","points":3,"solution":{"steps":[{"text_fr":"$A/A_0 = 3{,}4/13{,}6 = 0{,}25 = 1/4$ → 2 demi-vies."},{"text_fr":"Âge = $2 \\times 5730 = 11\\,460\\,\\text{ans}$."}],"final_answer_fr":"$\\approx 11\\,460$ ans"}},{"number":2,"stem_fr":"Pourquoi le C14 limite-t-il la datation à ~50 000 ans ?","points":2,"solution":{"steps":[{"text_fr":"Après ~9 demi-vies, $A/A_0 < 0{,}2\\%$ — sous le seuil de détection."},{"text_fr":"Au-delà, utiliser K-Ar, U-Pb pour les roches."}],"final_answer_fr":"~9 demi-vies max"}}]},{"number":4,"title_fr":"Datation U-Pb","points":5,"preamble_fr":"Roche : on mesure le rapport $^{206}\\text{Pb}/^{238}\\text{U} = 0{,}5$. Demi-vie $U-238 = 4{,}5 \\times 10^9$ ans.","questions":[{"number":1,"stem_fr":"Comment relier ce rapport à l''âge ?","points":3,"solution":{"steps":[{"text_fr":"Si $N_0$ atomes d''U au départ, après temps $t$ : $N_U = N_0 e^{-\\lambda t}$, et atomes de Pb produits : $N_{Pb} = N_0 - N_U$."},{"text_fr":"$N_{Pb}/N_U = e^{\\lambda t} - 1 = 0{,}5 \\iff e^{\\lambda t} = 1{,}5 \\iff t = \\ln 1{,}5/\\lambda$."}],"final_answer_fr":"$t = \\ln 1{,}5/\\lambda$"}},{"number":2,"stem_fr":"Calcul numérique.","points":2,"solution":{"steps":[{"text_fr":"$\\lambda = \\ln 2/(4{,}5 \\times 10^9)$."},{"text_fr":"$t = \\ln 1{,}5 \\cdot 4{,}5 \\times 10^9/\\ln 2 = 0{,}405 \\times 4{,}5 \\times 10^9/0{,}693 \\approx 2{,}6 \\times 10^9\\,\\text{ans}$."}],"final_answer_fr":"$\\approx 2{,}6$ Ga"}}]}]}'::jsonb WHERE code = 'svt_radioactivity_basics';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Dipôle RC (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Charge, décharge, constante de temps.","exercices":[{"number":1,"title_fr":"Charge","points":5,"preamble_fr":"$E = 10\\,\\text{V}$, $R = 1\\,\\text{k}\\Omega$, $C = 100\\,\\mu\\text{F}$.","questions":[{"number":1,"stem_fr":"Constante de temps.","points":1,"solution":{"steps":[{"text_fr":"$\\tau = R C = 10^3 \\times 10^{-4} = 0{,}1\\,\\text{s} = 100\\,\\text{ms}$."}],"final_answer_fr":"$\\tau = 100$ ms"}},{"number":2,"stem_fr":"Expression de $u_C(t)$.","points":1,"solution":{"steps":[{"text_fr":"$u_C(t) = 10(1 - e^{-t/0{,}1})\\,\\text{V}$."}],"final_answer_fr":"$10(1 - e^{-10t})$"}},{"number":3,"stem_fr":"Temps pour atteindre 95% de $E$.","points":2,"solution":{"steps":[{"text_fr":"$t \\approx 3\\tau = 0{,}3\\,\\text{s}$ (règle pratique)."}],"final_answer_fr":"$\\approx 0{,}3$ s"}},{"number":4,"stem_fr":"Énergie stockée à plein chargement.","points":1,"solution":{"steps":[{"text_fr":"$E_C = (1/2) C U^2 = 0{,}5 \\times 10^{-4} \\times 100 = 5\\,\\text{mJ}$."}],"final_answer_fr":"$5$ mJ"}}]},{"number":2,"title_fr":"Décharge","points":5,"preamble_fr":"Le même condensateur, chargé à 10 V, se décharge dans une résistance de 2 kΩ.","questions":[{"number":1,"stem_fr":"Nouvelle constante de temps.","points":1,"solution":{"steps":[{"text_fr":"$\\tau'' = 2000 \\times 10^{-4} = 0{,}2\\,\\text{s}$."}],"final_answer_fr":"$200$ ms"}},{"number":2,"stem_fr":"Tension à $t = \\tau''$.","points":2,"solution":{"steps":[{"text_fr":"$u_C = 10 e^{-1} \\approx 3{,}68\\,\\text{V}$."}],"final_answer_fr":"$\\approx 3{,}68$ V"}},{"number":3,"stem_fr":"Temps de demi-décharge.","points":2,"solution":{"steps":[{"text_fr":"$u_C = 5 \\iff t = \\tau'' \\ln 2 \\approx 0{,}14\\,\\text{s}$."}],"final_answer_fr":"$\\approx 0{,}14$ s"}}]},{"number":3,"title_fr":"Mesure de C","points":5,"preamble_fr":"On observe une décharge : 6 V à 3 V en 1,2 s avec R = 5 kΩ.","questions":[{"number":1,"stem_fr":"Constante $\\tau$.","points":2,"solution":{"steps":[{"text_fr":"Temps de demi-décharge $t_{1/2} = 1{,}2 = \\tau \\ln 2 \\iff \\tau = 1{,}2/0{,}693 \\approx 1{,}73\\,\\text{s}$."}],"final_answer_fr":"$\\approx 1{,}73$ s"}},{"number":2,"stem_fr":"Valeur de C.","points":2,"solution":{"steps":[{"text_fr":"$C = \\tau/R = 1{,}73/5000 \\approx 3{,}5 \\times 10^{-4}\\,\\text{F} = 350\\,\\mu\\text{F}$."}],"final_answer_fr":"$\\approx 350$ μF"}},{"number":3,"stem_fr":"Méthode standard ?","points":1,"solution":{"steps":[{"text_fr":"Chronométrer la chute à mi-amplitude est la méthode standard de mesure de $\\tau$."}],"final_answer_fr":"chronométrage $t_{1/2}$"}}]},{"number":4,"title_fr":"Application — flash","points":5,"preamble_fr":"Flash : $C = 1000\\,\\mu\\text{F}$, chargé à 250 V, décharge en 2 ms.","questions":[{"number":1,"stem_fr":"Énergie disponible.","points":2,"solution":{"steps":[{"text_fr":"$E = (1/2) C U^2 = 0{,}5 \\times 10^{-3} \\times 62500 = 31{,}25\\,\\text{J}$."}],"final_answer_fr":"$\\approx 31$ J"}},{"number":2,"stem_fr":"Puissance moyenne pendant le flash.","points":2,"solution":{"steps":[{"text_fr":"$P = E/t = 31{,}25/0{,}002 \\approx 15{,}6\\,\\text{kW}$."}],"final_answer_fr":"$\\approx 15{,}6$ kW"}},{"number":3,"stem_fr":"Résistance équivalente du tube ?","points":1,"solution":{"steps":[{"text_fr":"$\\tau = RC = 2\\,\\text{ms} \\Rightarrow R = 2\\,\\Omega$."}],"final_answer_fr":"$\\approx 2$ Ω"}}]}]}'::jsonb WHERE code = 'svt_rc_circuit';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — pH et solutions (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Calcul de pH, acides forts et faibles.","exercices":[{"number":1,"title_fr":"Calculs de pH","points":5,"preamble_fr":"À 25°C, $K_e = 10^{-14}$.","questions":[{"number":1,"stem_fr":"pH d''une solution de HCl à 0,01 mol/L.","points":1,"solution":{"steps":[{"text_fr":"Acide fort : $pH = -\\log 0{,}01 = 2$."}],"final_answer_fr":"$pH = 2$"}},{"number":2,"stem_fr":"pH d''une solution de NaOH à $10^{-3}$ mol/L.","points":2,"solution":{"steps":[{"text_fr":"$[\\text{OH}^-] = 10^{-3}$. $[\\text{H}_3\\text{O}^+] = 10^{-11}$. $pH = 11$."}],"final_answer_fr":"$pH = 11$"}},{"number":3,"stem_fr":"pH après dilution × 10 d''une solution acide à pH = 3.","points":2,"solution":{"steps":[{"text_fr":"Acide fort : $[\\text{H}_3\\text{O}^+]$ divisée par 10 → pH augmente de 1 → $pH = 4$."}],"final_answer_fr":"$pH = 4$"}}]},{"number":2,"title_fr":"Acide faible","points":5,"preamble_fr":"Acide acétique, pKa = 4,75, $C_0 = 0{,}1\\,\\text{mol/L}$.","questions":[{"number":1,"stem_fr":"pH par formule simplifiée.","points":2,"solution":{"steps":[{"text_fr":"$pH \\approx (pKa - \\log C_0)/2 = (4{,}75 + 1)/2 = 2{,}875$."}],"final_answer_fr":"$\\approx 2{,}88$"}},{"number":2,"stem_fr":"Taux de dissociation $\\alpha$.","points":2,"solution":{"steps":[{"text_fr":"$[\\text{H}_3\\text{O}^+] = 10^{-2{,}88} \\approx 1{,}33 \\times 10^{-3}\\,\\text{mol/L}$. $\\alpha = 1{,}33 \\times 10^{-3}/0{,}1 \\approx 1{,}3\\%$."}],"final_answer_fr":"$\\approx 1{,}3\\%$"}},{"number":3,"stem_fr":"L''acide est-il fortement ou faiblement dissocié ?","points":1,"solution":{"steps":[{"text_fr":"Faiblement (1,3% ≪ 100%). Cohérent avec l''approximation utilisée."}],"final_answer_fr":"faiblement"}}]},{"number":3,"title_fr":"Tampon","points":5,"preamble_fr":"Mélange CH₃COOH (0,1 mol/L) + CH₃COONa (0,1 mol/L), pKa = 4,75.","questions":[{"number":1,"stem_fr":"pH par Henderson-Hasselbalch.","points":2,"solution":{"steps":[{"text_fr":"$pH = pKa + \\log([\\text{A}^-]/[\\text{HA}]) = 4{,}75 + \\log 1 = 4{,}75$."}],"final_answer_fr":"$pH = 4{,}75$"}},{"number":2,"stem_fr":"Caractère tampon : ajout d''acide fort.","points":2,"solution":{"steps":[{"text_fr":"Les ions $\\text{H}_3\\text{O}^+$ ajoutés sont consommés par $\\text{A}^-$. Le rapport $[\\text{A}^-]/[\\text{HA}]$ varie peu → pH varie peu."}],"final_answer_fr":"pH stable"}},{"number":3,"stem_fr":"Pour avoir pH = 5,75, rapport ?","points":1,"solution":{"steps":[{"text_fr":"$5{,}75 = 4{,}75 + \\log r \\iff r = 10$. $[\\text{A}^-] = 10 \\times [\\text{HA}]$."}],"final_answer_fr":"$[A^-]/[HA] = 10$"}}]},{"number":4,"title_fr":"Prédominance","points":5,"preamble_fr":"Couple $\\text{NH}_4^+/\\text{NH}_3$, pKa = 9,25.","questions":[{"number":1,"stem_fr":"Diagramme de prédominance.","points":2,"solution":{"steps":[{"text_fr":"$pH < pKa$ : NH₄⁺ majoritaire. $pH > pKa$ : NH₃ majoritaire."}],"final_answer_fr":"frontière à pKa"}},{"number":2,"stem_fr":"À pH = 7, quelle forme prédomine ?","points":1,"solution":{"steps":[{"text_fr":"$pH = 7 < 9{,}25$ → $\\text{NH}_4^+$ majoritaire."}],"final_answer_fr":"NH₄⁺"}},{"number":3,"stem_fr":"À quel pH $[\\text{NH}_3] = [\\text{NH}_4^+]$ ?","points":2,"solution":{"steps":[{"text_fr":"À $pH = pKa = 9{,}25$."}],"final_answer_fr":"$pH = 9{,}25$"}}]}]}'::jsonb WHERE code = 'svt_ph';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Oxydoréduction (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Couples redox, piles, Faraday.","exercices":[{"number":1,"title_fr":"Demi-équations","points":5,"preamble_fr":"Écrire les demi-équations.","questions":[{"number":1,"stem_fr":"Couple Cu²⁺/Cu.","points":1,"solution":{"steps":[{"text_fr":"$\\text{Cu}^{2+} + 2 e^- \\rightleftharpoons \\text{Cu}$."}],"final_answer_fr":"$Cu^{2+} + 2e^- \\to Cu$"}},{"number":2,"stem_fr":"Couple Fe³⁺/Fe²⁺.","points":1,"solution":{"steps":[{"text_fr":"$\\text{Fe}^{3+} + e^- \\rightleftharpoons \\text{Fe}^{2+}$."}],"final_answer_fr":"$Fe^{3+} + e^- \\to Fe^{2+}$"}},{"number":3,"stem_fr":"Bilan global Zn + Cu²⁺.","points":3,"solution":{"steps":[{"text_fr":"Anode : $\\text{Zn} \\to \\text{Zn}^{2+} + 2 e^-$. Cathode : $\\text{Cu}^{2+} + 2 e^- \\to \\text{Cu}$."},{"text_fr":"Bilan : $\\text{Zn} + \\text{Cu}^{2+} \\to \\text{Zn}^{2+} + \\text{Cu}$."}],"final_answer_fr":"$Zn + Cu^{2+} \\to Zn^{2+} + Cu$"}}]},{"number":2,"title_fr":"Pile Daniell","points":5,"preamble_fr":"Pile Zn|Zn²⁺ ‖ Cu²⁺|Cu, courant 50 mA.","questions":[{"number":1,"stem_fr":"fem théorique.","points":1,"solution":{"steps":[{"text_fr":"$E = E°(Cu^{2+}/Cu) - E°(Zn^{2+}/Zn) = 0{,}34 - (-0{,}76) = 1{,}10\\,\\text{V}$."}],"final_answer_fr":"$1{,}10$ V"}},{"number":2,"stem_fr":"Quantité d''électricité après 1 h.","points":2,"solution":{"steps":[{"text_fr":"$Q = I t = 0{,}05 \\times 3600 = 180\\,\\text{C}$."}],"final_answer_fr":"$180$ C"}},{"number":3,"stem_fr":"Masse de Cu déposée (M = 63,5 g/mol, F = 96500).","points":3,"solution":{"steps":[{"text_fr":"$n_e = Q/F = 180/96500 \\approx 1{,}87 \\times 10^{-3}\\,\\text{mol}$."},{"text_fr":"$n_{Cu} = n_e/2 = 9{,}3 \\times 10^{-4}\\,\\text{mol}$. $m = 9{,}3 \\times 10^{-4} \\times 63{,}5 \\approx 59\\,\\text{mg}$."}],"final_answer_fr":"$\\approx 59$ mg"}}]},{"number":3,"title_fr":"Corrosion du fer","points":5,"preamble_fr":"Le fer rouille en présence d''humidité et d''oxygène.","questions":[{"number":1,"stem_fr":"Demi-équations.","points":3,"solution":{"steps":[{"text_fr":"Oxydation : $\\text{Fe} \\to \\text{Fe}^{2+} + 2 e^-$."},{"text_fr":"Réduction : $\\text{O}_2 + 2 \\text{H}_2\\text{O} + 4 e^- \\to 4 \\text{OH}^-$."},{"text_fr":"Le Fe²⁺ s''oxyde ensuite en Fe³⁺ → rouille (oxyde hydraté de fer III)."}],"final_answer_fr":"oxydation Fe, réduction $O_2$"}},{"number":2,"stem_fr":"Comment protéger ? 3 méthodes.","points":2,"solution":{"steps":[{"text_fr":"(1) Peinture ou plastification (barrière physique). (2) Galvanisation (zinc, anode sacrificielle). (3) Protection cathodique (Mg ou Zn relié au fer, qui s''oxyde à sa place)."}],"final_answer_fr":"peinture, galva, cathodique"}}]},{"number":4,"title_fr":"Électrolyse","points":5,"preamble_fr":"Électrolyse de CuSO₄ avec électrodes inertes, I = 0,5 A pendant 30 min.","questions":[{"number":1,"stem_fr":"Quels sont les produits à chaque électrode ?","points":3,"solution":{"steps":[{"text_fr":"Cathode (-) : $\\text{Cu}^{2+} + 2 e^- \\to \\text{Cu}$, dépôt de cuivre."},{"text_fr":"Anode (+) : $2 \\text{H}_2\\text{O} \\to \\text{O}_2 + 4 \\text{H}^+ + 4 e^-$, dégagement d''oxygène."}],"final_answer_fr":"Cu à cathode, $O_2$ à anode"}},{"number":2,"stem_fr":"Masse de Cu déposée.","points":2,"solution":{"steps":[{"text_fr":"$Q = I t = 0{,}5 \\times 1800 = 900\\,\\text{C}$. $n_e = 9{,}33 \\times 10^{-3}\\,\\text{mol}$. $n_{Cu} = 4{,}66 \\times 10^{-3}$. $m = 4{,}66 \\times 10^{-3} \\times 63{,}5 \\approx 296\\,\\text{mg}$."}],"final_answer_fr":"$\\approx 296$ mg"}}]}]}'::jsonb WHERE code = 'svt_redox_basics';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Chimie organique — esters (SVT)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Estérification, hydrolyse, saponification.","exercices":[{"number":1,"title_fr":"Équations","points":5,"preamble_fr":"Écrire.","questions":[{"number":1,"stem_fr":"Estérification entre acide éthanoïque et éthanol.","points":2,"solution":{"steps":[{"text_fr":"$\\text{CH}_3\\text{COOH} + \\text{CH}_3\\text{CH}_2\\text{OH} \\rightleftharpoons \\text{CH}_3\\text{COO-CH}_2\\text{CH}_3 + \\text{H}_2\\text{O}$."},{"text_fr":"Produit : éthanoate d''éthyle + eau."}],"final_answer_fr":"éthanoate d''éthyle"}},{"number":2,"stem_fr":"Caractéristiques de la réaction.","points":2,"solution":{"steps":[{"text_fr":"**Lente, limitée (K≈4), athermique** : T accélère mais ne déplace pas l''équilibre."}],"final_answer_fr":"lente, limitée, athermique"}},{"number":3,"stem_fr":"Catalyseur courant ?","points":1,"solution":{"steps":[{"text_fr":"H₂SO₄ concentré (catalyseur acide)."}],"final_answer_fr":"$H_2SO_4$"}}]},{"number":2,"title_fr":"Équilibre","points":5,"preamble_fr":"1 mol acide + 1 mol alcool, K = 4.","questions":[{"number":1,"stem_fr":"Avancement final.","points":3,"solution":{"steps":[{"text_fr":"$K = \\xi^2/(1-\\xi)^2 = 4 \\iff \\xi/(1-\\xi) = 2 \\iff \\xi = 2/3$."},{"text_fr":"67% de rendement."}],"final_answer_fr":"$\\xi = 2/3$, 67%"}},{"number":2,"stem_fr":"Avec excès d''alcool (2 mol au lieu de 1).","points":2,"solution":{"steps":[{"text_fr":"$K = \\xi^2/[(1-\\xi)(2-\\xi)] = 4$, résolution → $\\xi \\approx 0{,}85$. **Rendement augmenté à 85%**."}],"final_answer_fr":"$\\xi \\approx 0{,}85$, 85%"}}]},{"number":3,"title_fr":"Hydrolyse","points":5,"preamble_fr":"1 mol d''ester + 1 mol d''eau.","questions":[{"number":1,"stem_fr":"Avancement final.","points":3,"solution":{"steps":[{"text_fr":"Même équilibre atteint : 1/3 d''acide et alcool, 2/3 d''ester (vu de l''estérification). Donc 33% d''hydrolyse."},{"text_fr":"Démonstration : pour l''hydrolyse, K'' = 1/K = 0,25. $(1-\\xi)^2/\\xi^2 = 4 \\iff \\xi = 1/3$."}],"final_answer_fr":"$\\xi = 1/3$, 33%"}},{"number":2,"stem_fr":"Pourquoi 33% d''un côté et 67% de l''autre ?","points":2,"solution":{"steps":[{"text_fr":"Même équilibre atteint quel que soit le sens de départ. ''Avancement'' est défini par rapport à l''état initial. Vu de A→B : 67%. Vu de B→A : 33%."}],"final_answer_fr":"même équilibre"}}]},{"number":4,"title_fr":"Saponification","points":5,"preamble_fr":"Hydrolyse basique : ester + soude.","questions":[{"number":1,"stem_fr":"Équation et caractère totale.","points":3,"solution":{"steps":[{"text_fr":"$\\text{R-COO-R''} + \\text{OH}^- \\to \\text{R-COO}^- + \\text{R''-OH}$."},{"text_fr":"**Totale** car le carboxylate est très stable (résonance) et la base $\\text{OH}^-$ déplace l''équilibre vers ce produit."}],"final_answer_fr":"totale"}},{"number":2,"stem_fr":"Application industrielle.","points":2,"solution":{"steps":[{"text_fr":"**Fabrication des savons** : saponification des triglycérides (graisses végétales/animales) par la soude → carboxylate de sodium = savon."}],"final_answer_fr":"savons"}}]}]}'::jsonb WHERE code = 'svt_organic_basics';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Génétique humaine (lois de Mendel)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Hérédité monohybride et dihybride, ABO, daltonisme.","exercices":[{"number":1,"title_fr":"Monohybridisme","points":5,"preamble_fr":"Couleur des yeux : marron (B) dominant sur bleu (b).","questions":[{"number":1,"stem_fr":"Croisement BB × bb. F1 ?","points":2,"solution":{"steps":[{"text_fr":"100% Bb (hétérozygote, phénotype marron uniforme — 1ère loi de Mendel)."}],"final_answer_fr":"100% Bb, marron"}},{"number":2,"stem_fr":"F1 × F1 → F2 ratios ?","points":2,"solution":{"steps":[{"text_fr":"Bb × Bb → 1 BB : 2 Bb : 1 bb."},{"text_fr":"Phénotypiquement : **3 marron : 1 bleu** (2ème loi)."}],"final_answer_fr":"3:1"}},{"number":3,"stem_fr":"Deux parents marron ont un enfant aux yeux bleus. Génotypes ?","points":1,"solution":{"steps":[{"text_fr":"Enfant bb → chaque parent a donné un b → parents Bb (hétérozygotes)."}],"final_answer_fr":"Bb × Bb"}}]},{"number":2,"title_fr":"Dihybridisme","points":5,"preamble_fr":"Deux gènes indépendants : couleur (B/b) et taille (T/t, grand/petit).","questions":[{"number":1,"stem_fr":"BbTt × BbTt → F2 ratios.","points":3,"solution":{"steps":[{"text_fr":"3ème loi : assortiment indépendant. F2 phénotypique = $3:1 \\times 3:1 = 9:3:3:1$."},{"text_fr":"9 dominants/dominants : 3 dom/réc : 3 réc/dom : 1 réc/réc."}],"final_answer_fr":"9:3:3:1"}},{"number":2,"stem_fr":"Pourcentage attendu d''enfants aux yeux bleus et petits.","points":2,"solution":{"steps":[{"text_fr":"Récessif/récessif : 1/16 = 6,25%."}],"final_answer_fr":"6,25%"}}]},{"number":3,"title_fr":"Hérédité liée au sexe","points":5,"preamble_fr":"Daltonisme : récessif lié au X ($X^d$).","questions":[{"number":1,"stem_fr":"Femme XX, homme XY. Risques chez les fils d''une mère porteuse $X^D X^d$ × père sain $X^D Y$ ?","points":3,"solution":{"steps":[{"text_fr":"Fils : $X^d Y$ (daltoniens) ou $X^D Y$ (sains), proba 1/2 chacun."},{"text_fr":"Donc **50% des fils** sont daltoniens."}],"final_answer_fr":"50% des fils"}},{"number":2,"stem_fr":"Pourquoi le daltonisme est plus fréquent chez les hommes ?","points":2,"solution":{"steps":[{"text_fr":"Un seul X chez l''homme → un seul allèle suffit (XY → $X^d Y$ exprime)."},{"text_fr":"Femme XX → besoin des deux X récessifs ($X^d X^d$, rare)."},{"text_fr":"Femme XX peut être ''porteuse'' ($X^D X^d$) sans être atteinte."}],"final_answer_fr":"un seul X"}}]},{"number":4,"title_fr":"Groupes sanguins ABO","points":5,"preamble_fr":"Allèles I^A, I^B (codominants) et i (récessif).","questions":[{"number":1,"stem_fr":"Génotypes possibles pour chaque groupe sanguin.","points":3,"solution":{"steps":[{"text_fr":"A : I^A I^A ou I^A i. B : I^B I^B ou I^B i. AB : I^A I^B (codominance). O : ii."}],"final_answer_fr":"4 groupes, 6 génotypes"}},{"number":2,"stem_fr":"Deux parents A et B ont un enfant O. Possible ? Génotypes ?","points":2,"solution":{"steps":[{"text_fr":"Oui si parents I^A i (A) × I^B i (B) → enfant ii (O) possible (proba 1/4)."}],"final_answer_fr":"oui, parents Aa × Bb"}}]}]}'::jsonb WHERE code = 'svt_genetique_humaine';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Génétique des populations (Hardy-Weinberg)","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Fréquences alléliques, équilibre de Hardy-Weinberg.","exercices":[{"number":1,"title_fr":"Hardy-Weinberg","points":5,"preamble_fr":"Allèles A (dominant) et a (récessif), fréquences p et q.","questions":[{"number":1,"stem_fr":"Donner les fréquences génotypiques à l''équilibre.","points":2,"solution":{"steps":[{"text_fr":"$f(AA) = p^2$, $f(Aa) = 2pq$, $f(aa) = q^2$. Somme = $(p+q)^2 = 1$."}],"final_answer_fr":"$p^2 + 2pq + q^2 = 1$"}},{"number":2,"stem_fr":"Conditions de validité.","points":3,"solution":{"steps":[{"text_fr":"Population grande (pas de dérive)."},{"text_fr":"Pas de sélection (tous les génotypes ont même succès reproductif)."},{"text_fr":"Pas de mutation. Pas de migration. Accouplement au hasard (panmixie)."}],"final_answer_fr":"5 conditions"}}]},{"number":2,"title_fr":"Calculs","points":5,"preamble_fr":"Maladie récessive : 1 personne sur 2500 ($q^2 = 1/2500$).","questions":[{"number":1,"stem_fr":"Fréquence de l''allèle pathogène $q$.","points":2,"solution":{"steps":[{"text_fr":"$q = \\sqrt{1/2500} = 1/50 = 0{,}02$."}],"final_answer_fr":"$q = 0{,}02$"}},{"number":2,"stem_fr":"Fréquence des hétérozygotes (porteurs).","points":2,"solution":{"steps":[{"text_fr":"$2 p q = 2 \\times 0{,}98 \\times 0{,}02 \\approx 0{,}0392 \\approx 3{,}9\\%$."},{"text_fr":"100 fois plus de porteurs que de malades !"}],"final_answer_fr":"$\\approx 3{,}9\\%$"}},{"number":3,"stem_fr":"Proba qu''un couple au hasard ait un enfant malade.","points":1,"solution":{"steps":[{"text_fr":"Couple Aa × Aa : 1/4 d''enfant aa. Couple porteur : (0,039)² ≈ 0,15%, donc 0,15% × 1/4 = 0,04% — proche du taux observé."},{"text_fr":"(En réalité : ~1/2500 = 0,04%, cohérent.)"}],"final_answer_fr":"$\\approx 0{,}04\\%$"}}]},{"number":3,"title_fr":"Application — mucoviscidose","points":5,"preamble_fr":"Maladie autosomique récessive, fréquence ~1/2500 en France.","questions":[{"number":1,"stem_fr":"Estimation du nombre de porteurs sains en France (67 millions habitants).","points":3,"solution":{"steps":[{"text_fr":"$q \\approx 1/50$, fréquence de porteurs $\\approx 2pq \\approx 4\\%$."},{"text_fr":"Nombre : $0{,}04 \\times 67\\,\\text{M} \\approx 2{,}7\\,\\text{M}$ porteurs."}],"final_answer_fr":"$\\approx 2{,}7$ M"}},{"number":2,"stem_fr":"Risque pour deux porteurs.","points":2,"solution":{"steps":[{"text_fr":"Couple Aa × Aa : 1/4 d''enfants malades, 1/2 porteurs, 1/4 sains. **25% d''enfants malades**."}],"final_answer_fr":"25%"}}]},{"number":4,"title_fr":"Écart à Hardy-Weinberg","points":5,"preamble_fr":"Population : génotypes observés AA=400, Aa=400, aa=200.","questions":[{"number":1,"stem_fr":"Total et fréquences alléliques observées.","points":2,"solution":{"steps":[{"text_fr":"Total = 1000. Allèles A : $2 \\times 400 + 400 = 1200/2000 = 0{,}6$. Allèles a : 0,4."}],"final_answer_fr":"$p = 0{,}6$"}},{"number":2,"stem_fr":"Génotypes attendus sous H-W.","points":2,"solution":{"steps":[{"text_fr":"$p^2 = 0{,}36 \\to 360$, $2pq = 0{,}48 \\to 480$, $q^2 = 0{,}16 \\to 160$."}],"final_answer_fr":"360 : 480 : 160"}},{"number":3,"stem_fr":"Comparer aux observations. Conclusion ?","points":1,"solution":{"steps":[{"text_fr":"Observés (400, 400, 200) ≠ attendus (360, 480, 160). Plus d''homozygotes et moins d''hétérozygotes que prévu."},{"text_fr":"**Force évolutive** à l''œuvre : peut-être sélection contre les Aa, ou consanguinité (réduit Aa)."}],"final_answer_fr":"écart, force évolutive"}}]}]}'::jsonb WHERE code = 'svt_genetique_populations';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Diversification génétique","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Méiose, brassages interchromosomique et intrachromosomique.","exercices":[{"number":1,"title_fr":"Méiose","points":5,"preamble_fr":"Cellule mère diploïde (2n = 4).","questions":[{"number":1,"stem_fr":"Nombre et type de cellules produites.","points":2,"solution":{"steps":[{"text_fr":"**4 cellules haploïdes (n)** — les gamètes."},{"text_fr":"Une méiose = 2 divisions successives : méiose I (réductionnelle, séparation des homologues) puis méiose II (équationnelle, comme une mitose)."}],"final_answer_fr":"4 gamètes (n)"}},{"number":2,"stem_fr":"Différence avec la mitose.","points":3,"solution":{"steps":[{"text_fr":"Mitose : 1 division → 2 cellules **diploïdes** identiques à la mère. Reproduction conforme."},{"text_fr":"Méiose : 2 divisions → 4 cellules **haploïdes** **différentes** entre elles ET de la mère. Source de diversité."}],"final_answer_fr":"haploïde vs diploïde, identité"}}]},{"number":2,"title_fr":"Brassage interchromosomique","points":5,"preamble_fr":"Espèce à n = 3 paires.","questions":[{"number":1,"stem_fr":"Nombre de combinaisons possibles.","points":2,"solution":{"steps":[{"text_fr":"Chaque paire d''homologues s''oriente au hasard en métaphase I → $2^n = 2^3 = 8$ combinaisons gamétiques par parent."}],"final_answer_fr":"$2^n = 8$"}},{"number":2,"stem_fr":"Chez l''homme (n = 23), combien de combinaisons ?","points":2,"solution":{"steps":[{"text_fr":"$2^{23} \\approx 8{,}4 \\times 10^6$ — plus de 8 millions de combinaisons."}],"final_answer_fr":"$\\sim 8 \\times 10^6$"}},{"number":3,"stem_fr":"Avec la fécondation (2 gamètes), combinaisons en F1 ?","points":1,"solution":{"steps":[{"text_fr":"$2^{23} \\times 2^{23} = 2^{46} \\approx 7 \\times 10^{13}$. Soixante-dix mille milliards !"}],"final_answer_fr":"$\\sim 7 \\times 10^{13}$"}}]},{"number":3,"title_fr":"Brassage intrachromosomique","points":5,"preamble_fr":"Crossing-over en prophase I.","questions":[{"number":1,"stem_fr":"Mécanisme.","points":3,"solution":{"steps":[{"text_fr":"En prophase I, les chromosomes homologues s''apparient (bivalents)."},{"text_fr":"Des fragments s''échangent entre chromatides — **crossing-over**."},{"text_fr":"Résultat : chromosomes recombinés, allèles initialement liés peuvent se retrouver séparés."}],"final_answer_fr":"échange entre chromatides"}},{"number":2,"stem_fr":"Pourquoi le crossing-over augmente-t-il la diversité ?","points":2,"solution":{"steps":[{"text_fr":"Il **rebat les cartes** : crée des combinaisons d''allèles nouvelles, jamais vues dans les générations précédentes."},{"text_fr":"Combiné au brassage interchromosomique, multiplie encore la diversité gamétique."}],"final_answer_fr":"nouvelles combinaisons"}}]},{"number":4,"title_fr":"Fécondation","points":5,"preamble_fr":"Étape finale de la reproduction sexuée.","questions":[{"number":1,"stem_fr":"Quel rôle joue la fécondation dans la diversité ?","points":3,"solution":{"steps":[{"text_fr":"Elle **combine au hasard** un gamète mâle (parmi des millions) avec un gamète femelle (parmi des millions)."},{"text_fr":"La diversité totale = (gamètes ♂) × (gamètes ♀) ≈ $10^{13}$ chez l''humain."},{"text_fr":"**Chaque embryon humain est unique** — pas deux frères/sœurs identiques (sauf jumeaux monozygotes, issus d''un même embryon scindé)."}],"final_answer_fr":"combinaison aléatoire"}},{"number":2,"stem_fr":"Importance biologique.","points":2,"solution":{"steps":[{"text_fr":"Diversité = matière première de l''évolution (sélection naturelle agit sur cette variation)."},{"text_fr":"Permet l''adaptation aux changements environnementaux."}],"final_answer_fr":"adaptation, évolution"}}]}]}'::jsonb WHERE code = 'svt_diversification_genetique';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Mécanismes de l''évolution","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Sélection naturelle, dérive, mutations, spéciation.","exercices":[{"number":1,"title_fr":"Forces évolutives","points":5,"preamble_fr":"Identifier la force responsable.","questions":[{"number":1,"stem_fr":"Population de papillons dans une forêt polluée : ceux à ailes sombres survivent mieux (camouflage).","points":2,"solution":{"steps":[{"text_fr":"**Sélection naturelle** : les sombres sont mieux adaptés à l''environnement pollué (résistance aux prédateurs)."},{"text_fr":"Exemple historique réel : phalène du bouleau (Biston betularia) pendant la révolution industrielle anglaise."}],"final_answer_fr":"sélection naturelle"}},{"number":2,"stem_fr":"Petite île, 10 lézards arrivent. Après 100 générations, fréquences alléliques très différentes du continent.","points":2,"solution":{"steps":[{"text_fr":"**Dérive génétique** : effet du hasard fort dans petite population."},{"text_fr":"Effet fondateur : la petite pop initiale n''avait pas toute la variabilité du continent."}],"final_answer_fr":"dérive + effet fondateur"}},{"number":3,"stem_fr":"Apparition d''un nouvel allèle jamais vu.","points":1,"solution":{"steps":[{"text_fr":"**Mutation** : seule force qui crée de la nouveauté génétique."}],"final_answer_fr":"mutation"}}]},{"number":2,"title_fr":"Sélection naturelle (Darwin)","points":5,"preamble_fr":"Principes.","questions":[{"number":1,"stem_fr":"Énoncer les 4 conditions de la sélection naturelle.","points":3,"solution":{"steps":[{"text_fr":"(1) Variation : les individus diffèrent."},{"text_fr":"(2) Héritabilité : ces différences sont transmissibles."},{"text_fr":"(3) Compétition : ressources limitées, surabondance de descendants."},{"text_fr":"(4) Adaptation différentielle : certaines variations donnent un avantage reproductif."}],"final_answer_fr":"variation, hérédité, compétition, adaptation"}},{"number":2,"stem_fr":"Résultat à long terme ?","points":2,"solution":{"steps":[{"text_fr":"Les allèles ''favorables'' (= conférant succès reproductif accru) deviennent plus fréquents génération après génération."},{"text_fr":"À terme : adaptation de la population à son environnement."}],"final_answer_fr":"adaptation"}}]},{"number":3,"title_fr":"Spéciation","points":5,"preamble_fr":"Émergence de nouvelles espèces.","questions":[{"number":1,"stem_fr":"Critère d''espèce le plus utilisé.","points":2,"solution":{"steps":[{"text_fr":"**Isolement reproductif** (concept biologique de l''espèce, Mayr) : deux populations sont des espèces différentes si elles ne peuvent plus produire de descendance fertile."}],"final_answer_fr":"isolement reproductif"}},{"number":2,"stem_fr":"Spéciation allopatrique.","points":2,"solution":{"steps":[{"text_fr":"Séparation **géographique** (barrière physique) d''une population en deux sous-pops."},{"text_fr":"Évolution indépendante (mutations + sélection + dérive différentes) → divergence. Si retour de contact et reproduction impossible : 2 espèces."}],"final_answer_fr":"barrière géo → divergence"}},{"number":3,"stem_fr":"Exemple iconique.","points":1,"solution":{"steps":[{"text_fr":"**Pinsons des Galápagos** (Darwin) : 13 espèces dérivées d''un ancêtre commun, différenciées par la forme du bec selon le régime alimentaire disponible sur chaque île."}],"final_answer_fr":"pinsons de Galápagos"}}]},{"number":4,"title_fr":"Évolution humaine","points":5,"preamble_fr":"Quelques jalons.","questions":[{"number":1,"stem_fr":"Combien d''années depuis le dernier ancêtre commun homme-chimpanzé ?","points":2,"solution":{"steps":[{"text_fr":"Environ 7 millions d''années (horloge moléculaire + paléontologie)."}],"final_answer_fr":"$\\sim 7$ Ma"}},{"number":2,"stem_fr":"Les humains modernes (Homo sapiens) sont apparus il y a combien de temps ?","points":1,"solution":{"steps":[{"text_fr":"Environ 300 000 ans en Afrique."},{"text_fr":"Sortie d''Afrique vers -70 000 ans, colonisation mondiale."}],"final_answer_fr":"$\\sim 300\\,000$ ans"}},{"number":3,"stem_fr":"Sommes-nous toujours en évolution ?","points":2,"solution":{"steps":[{"text_fr":"Oui — exemples récents : persistance de la lactase à l''âge adulte (adaptation à l''élevage), résistance à certaines maladies."},{"text_fr":"Mais évolution lente à l''échelle d''une vie humaine."}],"final_answer_fr":"oui, lentement"}}]}]}'::jsonb WHERE code = 'svt_evolution';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Communication nerveuse","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Neurone, potentiel d''action, synapse.","exercices":[{"number":1,"title_fr":"Le neurone","points":5,"preamble_fr":"Cellule excitable.","questions":[{"number":1,"stem_fr":"Structure d''un neurone.","points":3,"solution":{"steps":[{"text_fr":"**Corps cellulaire** (soma) : noyau, organites."},{"text_fr":"**Dendrites** : extensions qui reçoivent les informations."},{"text_fr":"**Axone** : long prolongement unique qui propage les PA. Se termine par des **terminaisons axonales** où sont libérés les neurotransmetteurs."}],"final_answer_fr":"soma, dendrites, axone"}},{"number":2,"stem_fr":"Potentiel de repos d''un neurone.","points":2,"solution":{"steps":[{"text_fr":"Environ $-70\\,\\text{mV}$ (intérieur négatif). Maintenu par la pompe Na⁺/K⁺ et les canaux fuite."},{"text_fr":"Différence ionique : K⁺ surtout intracellulaire, Na⁺ surtout extracellulaire."}],"final_answer_fr":"$-70$ mV"}}]},{"number":2,"title_fr":"Potentiel d''action","points":5,"preamble_fr":"Mécanisme du PA.","questions":[{"number":1,"stem_fr":"Phases du PA.","points":4,"solution":{"steps":[{"text_fr":"**Dépolarisation** : ouverture canaux Na⁺ voltage-dépendants → entrée Na⁺ → potentiel passe à $+40\\,\\text{mV}$."},{"text_fr":"**Repolarisation** : fermeture Na⁺, ouverture K⁺ → sortie K⁺ → retour vers $-70\\,\\text{mV}$."},{"text_fr":"**Hyperpolarisation** transitoire (légèrement plus négatif que repos)."},{"text_fr":"**Période réfractaire** : un nouveau PA n''est pas immédiatement possible."}],"final_answer_fr":"4 phases"}},{"number":2,"stem_fr":"Loi du tout ou rien.","points":1,"solution":{"steps":[{"text_fr":"Un stimulus en dessous du seuil ne déclenche rien. Au-dessus, déclenche **toujours** un PA de même amplitude (~+40 mV). Le codage est par **fréquence** de PA, pas amplitude."}],"final_answer_fr":"tout ou rien"}}]},{"number":3,"title_fr":"Propagation et synapse","points":5,"preamble_fr":"Transmission de l''information.","questions":[{"number":1,"stem_fr":"Vitesse de propagation : myéline vs non myélinisé.","points":3,"solution":{"steps":[{"text_fr":"**Sans myéline** : ~1 m/s, propagation continue."},{"text_fr":"**Avec myéline** : jusqu''à 100 m/s, propagation **saltatoire** (de nœud de Ranvier en nœud)."},{"text_fr":"Sclérose en plaques = destruction de myéline → ralentissement et symptômes neurologiques variés."}],"final_answer_fr":"1 m/s vs 100 m/s"}},{"number":2,"stem_fr":"Transmission à la synapse.","points":2,"solution":{"steps":[{"text_fr":"PA présynaptique → entrée Ca²⁺ → fusion des vésicules → libération des **neurotransmetteurs** dans la fente synaptique."},{"text_fr":"Neurotransmetteurs se fixent sur récepteurs postsynaptiques → ouverture de canaux ioniques → nouveau PA (synapse excitatrice) ou inhibition (synapse inhibitrice)."}],"final_answer_fr":"chimique, vésicules"}}]},{"number":4,"title_fr":"Réflexe myotatique","points":5,"preamble_fr":"Le réflexe rotulien : tap sous le genou → extension de la jambe.","questions":[{"number":1,"stem_fr":"Tracer le circuit du réflexe.","points":3,"solution":{"steps":[{"text_fr":"Étirement du muscle (récepteurs fuseaux neuromusculaires)."},{"text_fr":"Neurone sensitif (afférent) → moelle épinière."},{"text_fr":"Synapse directe avec neurone moteur (efférent) → contraction du muscle."},{"text_fr":"**Arc réflexe monosynaptique** : pas de cerveau impliqué, ultra rapide (~50 ms)."}],"final_answer_fr":"étirement → moelle → contraction"}},{"number":2,"stem_fr":"Pourquoi tester ce réflexe en consultation ?","points":2,"solution":{"steps":[{"text_fr":"Évalue l''intégrité du circuit nerveux périphérique."},{"text_fr":"Réflexe absent = lésion (nerf ou moelle). Réflexe exagéré = lésion centrale (cerveau)."}],"final_answer_fr":"évalue circuit nerveux"}}]}]}'::jsonb WHERE code = 'svt_communication_nerveuse';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Communication hormonale","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Glandes endocrines, régulation, rétrocontrôle.","exercices":[{"number":1,"title_fr":"Hormones et glandes","points":5,"preamble_fr":"Caractéristiques.","questions":[{"number":1,"stem_fr":"Définition d''une hormone.","points":2,"solution":{"steps":[{"text_fr":"Molécule sécrétée par une glande endocrine dans le sang, qui agit à distance sur des **cellules cibles** porteuses de récepteurs spécifiques."}],"final_answer_fr":"messager sanguin"}},{"number":2,"stem_fr":"5 glandes endocrines majeures et leur hormone caractéristique.","points":3,"solution":{"steps":[{"text_fr":"**Hypophyse** : nombreuses hormones (GH, ACTH, FSH/LH...)."},{"text_fr":"**Thyroïde** : thyroxine (T4) — régule le métabolisme."},{"text_fr":"**Pancréas** : insuline et glucagon — régulent la glycémie."},{"text_fr":"**Surrénales** : adrénaline (stress aigu), cortisol (stress chronique)."},{"text_fr":"**Gonades** : testostérone (♂), œstrogènes/progestérone (♀)."}],"final_answer_fr":"hypophyse, thyroïde, pancréas, surrénales, gonades"}}]},{"number":2,"title_fr":"Régulation glycémique","points":5,"preamble_fr":"Glycémie normale : 0,8-1,1 g/L.","questions":[{"number":1,"stem_fr":"Que se passe-t-il après un repas riche en sucres ?","points":3,"solution":{"steps":[{"text_fr":"Glycémie ↑ détectée par les cellules β du pancréas → libération d''**insuline**."},{"text_fr":"L''insuline fait entrer le glucose dans les cellules (foie, muscle) — stockage en glycogène."},{"text_fr":"Glycémie revient à la normale → arrêt de l''insuline (rétrocontrôle négatif)."}],"final_answer_fr":"insuline → baisse glycémie"}},{"number":2,"stem_fr":"Pendant le jeûne ?","points":2,"solution":{"steps":[{"text_fr":"Glycémie ↓ → cellules α du pancréas → **glucagon**."},{"text_fr":"Glucagon active la glycogénolyse hépatique → libération de glucose → glycémie remonte."}],"final_answer_fr":"glucagon → hausse"}}]},{"number":3,"title_fr":"Diabète","points":5,"preamble_fr":"Pathologie de la régulation.","questions":[{"number":1,"stem_fr":"Diabète de type 1.","points":3,"solution":{"steps":[{"text_fr":"Maladie auto-immune : destruction des cellules β pancréatiques."},{"text_fr":"Plus d''insuline produite → glycémie ↑ ↑ → traitement par insuline injectable à vie."},{"text_fr":"Apparition généralement jeune (enfance/adolescence). ~10% des diabètes."}],"final_answer_fr":"manque d''insuline"}},{"number":2,"stem_fr":"Diabète de type 2.","points":2,"solution":{"steps":[{"text_fr":"Résistance à l''insuline : les cellules ne répondent plus correctement."},{"text_fr":"Plus fréquent (~90%), lié au surpoids/sédentarité, apparition adulte. Traitement : régime, activité, médicaments oraux, parfois insuline."}],"final_answer_fr":"résistance à l''insuline"}}]},{"number":4,"title_fr":"Axe hypothalamo-hypophysaire","points":5,"preamble_fr":"Régulation hiérarchique.","questions":[{"number":1,"stem_fr":"Décrire l''axe hypothalamo-hypophyso-thyroïdien.","points":3,"solution":{"steps":[{"text_fr":"Hypothalamus → TRH (neurohormone) → hypophyse antérieure → TSH → thyroïde → T3/T4."},{"text_fr":"Les T3/T4 exercent un **rétrocontrôle négatif** sur hypothalamus et hypophyse → diminution de TRH et TSH si T3/T4 élevées."}],"final_answer_fr":"cascade régulée"}},{"number":2,"stem_fr":"Pourquoi un rétrocontrôle négatif ?","points":2,"solution":{"steps":[{"text_fr":"Pour **stabiliser** le taux d''hormone : si trop, inhibition de la production ; si pas assez, stimulation. Effet thermostat."},{"text_fr":"Sans rétrocontrôle : production explosive ou absence — incompatible avec la vie."}],"final_answer_fr":"stabilisation"}}]}]}'::jsonb WHERE code = 'svt_communication_hormonale';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Immunité","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Immunité innée, acquise, vaccination.","exercices":[{"number":1,"title_fr":"Immunité innée vs acquise","points":5,"preamble_fr":"Deux lignes de défense.","questions":[{"number":1,"stem_fr":"Caractéristiques de l''immunité innée.","points":3,"solution":{"steps":[{"text_fr":"**Présente dès la naissance**, immédiate (quelques minutes-heures)."},{"text_fr":"**Non-spécifique** : même réponse contre tout pathogène."},{"text_fr":"**Pas de mémoire** : pas d''amélioration aux contacts répétés."},{"text_fr":"Acteurs : barrières (peau, muqueuses), phagocytes (macrophages, neutrophiles), inflammation, complément."}],"final_answer_fr":"rapide, non-spécifique"}},{"number":2,"stem_fr":"Caractéristiques de l''immunité acquise.","points":2,"solution":{"steps":[{"text_fr":"**Acquise au cours de la vie** (après contact avec antigène). Lente (plusieurs jours à la 1ère exposition, quelques heures aux suivantes)."},{"text_fr":"**Spécifique** : un récepteur reconnait un antigène précis."},{"text_fr":"**Avec mémoire** : réponse plus rapide et plus forte aux contacts ultérieurs."}],"final_answer_fr":"lente, spécifique, mémoire"}}]},{"number":2,"title_fr":"Lymphocytes B et T","points":5,"preamble_fr":"Les soldats de l''immunité acquise.","questions":[{"number":1,"stem_fr":"Lymphocytes B → réponse humorale.","points":3,"solution":{"steps":[{"text_fr":"Les LB reconnaissent les antigènes (libres dans le sang ou portés par cellules infectées) via leurs récepteurs (BCR)."},{"text_fr":"Activation → différenciation en **plasmocytes** producteurs d''**anticorps** spécifiques."},{"text_fr":"Anticorps neutralisent l''antigène (agrégation, opsonisation) ou activent le complément."}],"final_answer_fr":"LB → anticorps"}},{"number":2,"stem_fr":"Lymphocytes T cytotoxiques → réponse cellulaire.","points":2,"solution":{"steps":[{"text_fr":"Les LT8 reconnaissent les cellules infectées (qui présentent des peptides viraux sur leur MHC I)."},{"text_fr":"Activation → destruction des cellules infectées par perforine + granzymes (apoptose induite)."}],"final_answer_fr":"LT8 → destruction cellulaire"}}]},{"number":3,"title_fr":"Vaccination","points":5,"preamble_fr":"Stratégie préventive.","questions":[{"number":1,"stem_fr":"Principe.","points":3,"solution":{"steps":[{"text_fr":"Injection d''antigènes (microbes atténués, inactivés, fragments, ARN messager...) **sans pathogénicité**."},{"text_fr":"Le système immunitaire active une réponse acquise et produit des **cellules mémoire**."},{"text_fr":"Lors d''une rencontre ultérieure avec le vrai pathogène : réponse immédiate et puissante → protection."}],"final_answer_fr":"mémoire immunitaire"}},{"number":2,"stem_fr":"Pourquoi certains vaccins nécessitent des rappels ?","points":2,"solution":{"steps":[{"text_fr":"La mémoire immunitaire **décline** avec le temps."},{"text_fr":"Rappels stimulent une nouvelle production d''anticorps et entretiennent la population de cellules mémoire."}],"final_answer_fr":"déclin de mémoire"}}]},{"number":4,"title_fr":"VIH et SIDA","points":5,"preamble_fr":"Mécanisme d''attaque immunitaire.","questions":[{"number":1,"stem_fr":"Comment le VIH attaque-t-il le système immunitaire ?","points":3,"solution":{"steps":[{"text_fr":"Le VIH a une affinité pour les **récepteurs CD4** présents sur les LT4 auxiliaires (chef d''orchestre de la réponse immunitaire)."},{"text_fr":"Le virus entre dans la cellule, intègre son génome (rétrovirus), se multiplie, détruit la cellule."},{"text_fr":"Progressive **diminution des LT4** : population normale ~1000/mm³ → SIDA déclaré si <200/mm³."}],"final_answer_fr":"détruit LT4"}},{"number":2,"stem_fr":"Pourquoi le SIDA est-il mortel ?","points":2,"solution":{"steps":[{"text_fr":"Effondrement de l''immunité acquise → vulnérabilité aux **infections opportunistes** (pneumocystose, toxoplasmose, candidose, etc.) et à certains cancers (sarcome de Kaposi)."},{"text_fr":"Traitement antirétroviral : rend la maladie chronique gérable mais pas curable. Espérance de vie quasi-normale sous traitement."}],"final_answer_fr":"infections opportunistes"}}]}]}'::jsonb WHERE code = 'svt_immunite';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Tectonique des plaques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Lithosphère, dorsales, subduction, failles transformantes.","exercices":[{"number":1,"title_fr":"Structure de la Terre","points":5,"preamble_fr":"Couches.","questions":[{"number":1,"stem_fr":"De la surface au centre.","points":3,"solution":{"steps":[{"text_fr":"**Croûte** (5-70 km) : continentale (granite) ou océanique (basalte)."},{"text_fr":"**Manteau** (jusqu''à 2900 km) : supérieur (lithosphérique rigide + asthénosphérique ductile) et inférieur."},{"text_fr":"**Noyau** : externe liquide (2900-5150 km), interne solide (5150-6370 km) — Fe-Ni."}],"final_answer_fr":"croûte, manteau, noyau"}},{"number":2,"stem_fr":"Différence lithosphère / asthénosphère.","points":2,"solution":{"steps":[{"text_fr":"**Lithosphère** : croûte + manteau supérieur rigide (~100 km épaisseur). Fragmentée en plaques."},{"text_fr":"**Asthénosphère** : manteau supérieur ductile (déforme lentement). C''est sur elle que glissent les plaques."}],"final_answer_fr":"rigide vs ductile"}}]},{"number":2,"title_fr":"Frontières de plaques","points":5,"preamble_fr":"Trois types.","questions":[{"number":1,"stem_fr":"Frontière divergente (dorsale).","points":3,"solution":{"steps":[{"text_fr":"Deux plaques s''écartent (~1-10 cm/an)."},{"text_fr":"Le manteau remonte par décompression → fusion partielle → **nouveau magma** qui durcit en basalte = **nouvelle croûte océanique**."},{"text_fr":"Exemple : dorsale médio-atlantique (Islande, là où elle émerge)."}],"final_answer_fr":"création de croûte"}},{"number":2,"stem_fr":"Subduction (convergente).","points":3,"solution":{"steps":[{"text_fr":"Une plaque océanique (plus dense) plonge sous une plaque continentale."},{"text_fr":"Provoque : **fosse océanique**, **séismes profonds**, **volcanisme explosif** (eau libérée → fusion du manteau)."},{"text_fr":"Exemple : Cordillère des Andes (plaque Nazca sous Sud-Amérique)."}],"final_answer_fr":"plaque dense plonge"}},{"number":3,"stem_fr":"Faille transformante.","points":1,"solution":{"steps":[{"text_fr":"Glissement latéral sans création ni destruction. Faille de San Andreas (Californie) — séismes fréquents."}],"final_answer_fr":"glissement latéral"}}]},{"number":3,"title_fr":"Preuves de la tectonique","points":5,"preamble_fr":"Comment Wegener a-t-il convaincu (a posteriori) ?","questions":[{"number":1,"stem_fr":"Trois preuves historiques.","points":3,"solution":{"steps":[{"text_fr":"(1) **Forme des continents** : Afrique et Amérique du Sud s''emboîtent (Wegener, 1912)."},{"text_fr":"(2) **Fossiles communs** : Mesosaurus (reptile) en Afrique et Amérique du Sud — mais incapable de traverser les océans."},{"text_fr":"(3) **Roches similaires** sur les deux côtés de l''Atlantique : continuité géologique avant séparation."}],"final_answer_fr":"forme, fossiles, roches"}},{"number":2,"stem_fr":"Preuve moderne décisive : paléomagnétisme.","points":2,"solution":{"steps":[{"text_fr":"Les basaltes de la dorsale enregistrent le champ magnétique terrestre quand ils se solidifient."},{"text_fr":"**Bandes magnétiques alternées symétriques** de part et d''autre de la dorsale → preuve d''expansion océanique continue."},{"text_fr":"Confirme l''âge croissant des roches en s''éloignant de la dorsale."}],"final_answer_fr":"paléomagnétisme symétrique"}}]},{"number":4,"title_fr":"Conséquences sismiques","points":5,"preamble_fr":"Séismes liés aux frontières.","questions":[{"number":1,"stem_fr":"Où sont concentrés les séismes mondiaux ?","points":2,"solution":{"steps":[{"text_fr":"Aux **frontières de plaques** (95% des séismes). Le ''feu'' du Pacifique (ceinture périphérique) est le plus actif."},{"text_fr":"Profondeurs variables : superficiels aux dorsales, jusqu''à 700 km aux subductions."}],"final_answer_fr":"frontières actives"}},{"number":2,"stem_fr":"Échelle de magnitude.","points":2,"solution":{"steps":[{"text_fr":"**Échelle de Richter** (logarithmique) : magnitude 6 = 10× énergie de magnitude 5."},{"text_fr":"Magnitude 9 = catastrophique (Tohoku 2011, Sumatra 2004)."}],"final_answer_fr":"Richter logarithmique"}},{"number":3,"stem_fr":"Magnitude vs intensité.","points":1,"solution":{"steps":[{"text_fr":"**Magnitude** : énergie libérée (mesurée). **Intensité** (Mercalli) : effets observés sur place (varie selon la distance, le sol)."}],"final_answer_fr":"énergie vs effet"}}]}]}'::jsonb WHERE code = 'svt_tectonique_plaques';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Géochronologie","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Datation absolue et relative.","exercices":[{"number":1,"title_fr":"Datation relative","points":5,"preamble_fr":"Principes stratigraphiques.","questions":[{"number":1,"stem_fr":"Principe de superposition.","points":2,"solution":{"steps":[{"text_fr":"Dans une série sédimentaire non déformée, les couches inférieures sont les plus **anciennes**, les supérieures sont les plus **récentes**."},{"text_fr":"Stratigraphie = lecture chronologique des dépôts."}],"final_answer_fr":"inférieur = ancien"}},{"number":2,"stem_fr":"Principe de recoupement.","points":2,"solution":{"steps":[{"text_fr":"Toute formation qui en **traverse** une autre lui est **postérieure**."},{"text_fr":"Exemple : une faille qui coupe une couche est plus jeune que cette couche."}],"final_answer_fr":"recoupant = postérieur"}},{"number":3,"stem_fr":"Principe d''identité paléontologique.","points":1,"solution":{"steps":[{"text_fr":"Deux couches contenant les mêmes **fossiles stratigraphiques** (espèces rapidement disparues, largement réparties) sont du même âge."}],"final_answer_fr":"mêmes fossiles = contemporain"}}]},{"number":2,"title_fr":"Datation au C14","points":5,"preamble_fr":"Demi-vie 5730 ans.","questions":[{"number":1,"stem_fr":"Un os à 50% d''activité initiale. Âge ?","points":1,"solution":{"steps":[{"text_fr":"1 demi-vie : 5730 ans."}],"final_answer_fr":"5730 ans"}},{"number":2,"stem_fr":"Un échantillon à 6,25% (1/16) d''activité.","points":2,"solution":{"steps":[{"text_fr":"$1/16 = 1/2^4$ → 4 demi-vies. Âge = $4 \\times 5730 = 22\\,920\\,\\text{ans}$."}],"final_answer_fr":"$\\approx 22\\,920$ ans"}},{"number":3,"stem_fr":"Limite supérieure de la méthode et alternatives.","points":2,"solution":{"steps":[{"text_fr":"Vers 50 000 ans (~9 demi-vies), activité trop faible à mesurer."},{"text_fr":"Au-delà : K-Ar (millions d''années), U-Pb (milliards d''années)."}],"final_answer_fr":"~50 000 ans"}}]},{"number":3,"title_fr":"Datation K-Ar","points":5,"preamble_fr":"Demi-vie K40 = 1,25 milliards d''années.","questions":[{"number":1,"stem_fr":"Roche volcanique : rapport $Ar/K = 1$. Âge ?","points":3,"solution":{"steps":[{"text_fr":"Si $N_K = N_{Ar}$, alors la moitié du K initial s''est désintégrée → 1 demi-vie."},{"text_fr":"Âge = 1,25 Ga (milliards d''années)."}],"final_answer_fr":"1,25 Ga"}},{"number":2,"stem_fr":"Application : datation de l''âge des roches lunaires (Apollo).","points":2,"solution":{"steps":[{"text_fr":"La Lune s''est formée il y a ~4,5 Ga (peu après la Terre)."},{"text_fr":"Les roches lunaires ont entre 3,2 et 4,5 Ga — beaucoup plus anciennes que les plus vieilles roches terrestres (rares au-delà de 3 Ga car recyclées par la tectonique)."}],"final_answer_fr":"3-4,5 Ga"}}]},{"number":4,"title_fr":"Échelle géologique","points":5,"preamble_fr":"Repères temporels.","questions":[{"number":1,"stem_fr":"Âge de la Terre.","points":1,"solution":{"steps":[{"text_fr":"4,57 milliards d''années (datation U-Pb sur météorites primitives)."}],"final_answer_fr":"4,57 Ga"}},{"number":2,"stem_fr":"Trois ères principales (du plus ancien au plus récent).","points":2,"solution":{"steps":[{"text_fr":"**Paléozoïque** (-541 à -252 Ma) : invertébrés, premiers vertébrés."},{"text_fr":"**Mésozoïque** (-252 à -66 Ma) : dinosaures."},{"text_fr":"**Cénozoïque** (-66 Ma à aujourd''hui) : mammifères, humains."},{"text_fr":"Avant : Précambrien (de la formation de la Terre à -541 Ma) — 88% de l''histoire."}],"final_answer_fr":"Paléozoïque, Mésozoïque, Cénozoïque"}},{"number":3,"stem_fr":"Extinction Cretacé-Tertiaire.","points":2,"solution":{"steps":[{"text_fr":"Il y a 66 Ma, météorite gigantesque (cratère de Chicxulub, Mexique) → hiver d''impact → extinction de ~75% des espèces, dont les dinosaures non-aviens."},{"text_fr":"Permet l''essor des mammifères, puis des primates, puis des humains."}],"final_answer_fr":"-66 Ma, météorite, dinosaures"}}]}]}'::jsonb WHERE code = 'svt_geochronologie';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Métamorphisme","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Transformation des roches à l''état solide.","exercices":[{"number":1,"title_fr":"Définition et causes","points":5,"preamble_fr":"Comprendre le phénomène.","questions":[{"number":1,"stem_fr":"Métamorphisme = ?","points":2,"solution":{"steps":[{"text_fr":"Transformation d''une roche **à l''état solide** sous l''effet d''augmentation de **pression**, **température**, ou des **fluides**."},{"text_fr":"Pas de fusion (au-delà = magmatisme)."}],"final_answer_fr":"solide, P-T-fluides"}},{"number":2,"stem_fr":"Trois grands contextes.","points":3,"solution":{"steps":[{"text_fr":"**De contact** : faible P, forte T, autour d''intrusions magmatiques. Auréole de contact."},{"text_fr":"**Régional** : grandes échelles, lors des collisions tectoniques (chaînes de montagnes). P et T élevées."},{"text_fr":"**De subduction** : forte P, T modérée (HP-BT). Roches caractéristiques : éclogites, schistes bleus."}],"final_answer_fr":"contact, régional, subduction"}}]},{"number":2,"title_fr":"Faciès métamorphiques","points":5,"preamble_fr":"Domaines P-T.","questions":[{"number":1,"stem_fr":"Citer 3 faciès classiques.","points":3,"solution":{"steps":[{"text_fr":"**Schiste vert** : faible degré (~300°C, ~3 kbar). Chlorite, épidote."},{"text_fr":"**Amphibolite** : moyen degré (~600°C, ~6 kbar). Amphibole, plagioclase."},{"text_fr":"**Granulite** : haut degré (~800°C, ~8 kbar). Pyroxène, grenat, perte d''eau."},{"text_fr":"**Éclogite** : très haute pression (>700°C, >12 kbar). Pyroxène jadeitique + grenat, chimie particulière."}],"final_answer_fr":"4 faciès"}},{"number":2,"stem_fr":"Comment ''lire'' les conditions P-T d''une roche ?","points":2,"solution":{"steps":[{"text_fr":"Les **minéraux index** indiquent les conditions de leur formation."},{"text_fr":"Exemple : disthène = HP, andalousite = BP-HT, sillimanite = HT. Ce sont 3 polymorphes (même formule Al₂SiO₅, différentes stabilités)."}],"final_answer_fr":"minéraux index"}}]},{"number":3,"title_fr":"Trajets P-T-t","points":5,"preamble_fr":"Histoire métamorphique.","questions":[{"number":1,"stem_fr":"Qu''est-ce qu''un trajet P-T-t ?","points":3,"solution":{"steps":[{"text_fr":"Évolution de la roche en pression, température, et temps."},{"text_fr":"Une roche subduite va plonger (P augmente, T augmente plus lentement), atteindre un pic, puis remonter (exhumation : P diminue, parfois T continue d''augmenter brièvement)."},{"text_fr":"Permet de reconstituer l''histoire tectonique d''une région."}],"final_answer_fr":"P, T, temps"}},{"number":2,"stem_fr":"Importance des éclogites de surface.","points":2,"solution":{"steps":[{"text_fr":"Une éclogite à la surface raconte une **subduction passée** suivie d''une **exhumation rapide** (sinon la roche réagirait et perdrait sa signature HP)."},{"text_fr":"Les Alpes contiennent des éclogites — vestiges de la fermeture de l''océan Téthys."}],"final_answer_fr":"subduction passée"}}]},{"number":4,"title_fr":"Métamorphisme et tectonique","points":5,"preamble_fr":"Lien avec la dynamique terrestre.","questions":[{"number":1,"stem_fr":"Pourquoi observe-t-on plus de roches métamorphiques dans les chaînes de montagnes ?","points":3,"solution":{"steps":[{"text_fr":"Les collisions tectoniques (ex. Himalaya) génèrent des **épaississements crustaux** énormes (parfois >70 km)."},{"text_fr":"Les roches profondes subissent des P-T élevées → métamorphisme régional intense."},{"text_fr":"L''**érosion** ultérieure expose ces roches métamorphiques à la surface."}],"final_answer_fr":"collision + érosion"}},{"number":2,"stem_fr":"Trois exemples de chaînes avec roches métamorphiques.","points":2,"solution":{"steps":[{"text_fr":"Alpes (collision Afrique-Eurasie). Himalaya (collision Inde-Asie). Atlas marocain (témoignages de collision plus ancienne)."}],"final_answer_fr":"Alpes, Himalaya, Atlas"}}]}]}'::jsonb WHERE code = 'svt_metamorphisme';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Énergie cellulaire","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Photosynthèse, respiration, ATP.","exercices":[{"number":1,"title_fr":"Photosynthèse","points":5,"preamble_fr":"Énergie lumineuse → énergie chimique.","questions":[{"number":1,"stem_fr":"Équation bilan.","points":2,"solution":{"steps":[{"text_fr":"$6\\,\\text{CO}_2 + 6\\,\\text{H}_2\\text{O} + \\text{lumière} \\to \\text{C}_6\\text{H}_{12}\\text{O}_6 + 6\\,\\text{O}_2$."}],"final_answer_fr":"$6CO_2 + 6H_2O \\to C_6H_{12}O_6 + 6O_2$"}},{"number":2,"stem_fr":"Deux phases.","points":3,"solution":{"steps":[{"text_fr":"**Phase claire (thylakoïdes)** : la lumière dissocie l''eau ($2 H_2O \\to O_2 + 4 H^+ + 4 e^-$) et produit ATP + NADPH. **Source de l''O₂ atmosphérique** !"},{"text_fr":"**Phase sombre (stroma, cycle de Calvin)** : utilise ATP + NADPH pour réduire CO₂ en glucose."},{"text_fr":"La phase sombre ne nécessite pas de lumière directe — mais a besoin des produits de la phase claire."}],"final_answer_fr":"claire + Calvin"}}]},{"number":2,"title_fr":"Respiration cellulaire","points":5,"preamble_fr":"Inverse de la photosynthèse.","questions":[{"number":1,"stem_fr":"Équation bilan.","points":2,"solution":{"steps":[{"text_fr":"$\\text{C}_6\\text{H}_{12}\\text{O}_6 + 6\\,\\text{O}_2 \\to 6\\,\\text{CO}_2 + 6\\,\\text{H}_2\\text{O} + \\text{énergie (ATP)}$."}],"final_answer_fr":"glucose + $O_2 \\to CO_2$ + $H_2O$ + ATP"}},{"number":2,"stem_fr":"Trois étapes.","points":3,"solution":{"steps":[{"text_fr":"**Glycolyse** (cytoplasme) : glucose (6C) → 2 pyruvate (3C). Bilan : 2 ATP + 2 NADH."},{"text_fr":"**Cycle de Krebs** (matrice mitochondriale) : pyruvate → CO₂ + NADH + FADH₂."},{"text_fr":"**Chaîne respiratoire** (membrane interne mitochondrie) : O₂ accepte les électrons, gradient de protons → ATP synthase → ATP. Production massive : ~32 ATP."},{"text_fr":"**Bilan total** : ~36 ATP par glucose oxydé."}],"final_answer_fr":"glycolyse, Krebs, chaîne"}}]},{"number":3,"title_fr":"Fermentation","points":5,"preamble_fr":"Sans oxygène.","questions":[{"number":1,"stem_fr":"Bilan de la fermentation lactique.","points":2,"solution":{"steps":[{"text_fr":"$\\text{glucose} \\to 2\\,\\text{lactate} + 2\\,\\text{ATP}$ (faible rendement)."},{"text_fr":"Se produit dans les muscles privés d''O₂ (effort intense → acide lactique → courbatures)."}],"final_answer_fr":"glucose → lactate"}},{"number":2,"stem_fr":"Pourquoi rendement faible vs respiration aérobie ?","points":2,"solution":{"steps":[{"text_fr":"Sans O₂ accepteur final, on s''arrête à la glycolyse (2 ATP). Pas de cycle de Krebs ni chaîne respiratoire."},{"text_fr":"Respiration aérobie 18× plus efficace énergétiquement par glucose (36 vs 2 ATP)."}],"final_answer_fr":"pas de chaîne respiratoire"}},{"number":3,"stem_fr":"Application industrielle.","points":1,"solution":{"steps":[{"text_fr":"Fermentation alcoolique par levures : glucose → 2 éthanol + 2 CO₂. Base de la fabrication de pain, vin, bière."}],"final_answer_fr":"pain, vin, bière"}}]},{"number":4,"title_fr":"Couplage photosynthèse-respiration","points":5,"preamble_fr":"Vue d''ensemble.","questions":[{"number":1,"stem_fr":"Pourquoi sont-elles complémentaires à l''échelle planétaire ?","points":3,"solution":{"steps":[{"text_fr":"**Photosynthèse** : fixe le CO₂, libère l''O₂, produit la matière organique."},{"text_fr":"**Respiration** : oxyde la matière organique, libère le CO₂, consomme l''O₂."},{"text_fr":"Cycle global du carbone et de l''oxygène : équilibre maintenu sur l''échelle des siècles."}],"final_answer_fr":"cycles couplés C/O₂"}},{"number":2,"stem_fr":"Effet humain sur ce couplage.","points":2,"solution":{"steps":[{"text_fr":"Combustion des énergies fossiles (libération du C stocké il y a des millions d''années) → augmentation du CO₂ atmosphérique."},{"text_fr":"Déforestation → diminution de la photosynthèse. Conséquence : effet de serre, changement climatique."}],"final_answer_fr":"déséquilibre actuel"}}]}]}'::jsonb WHERE code = 'svt_energie_cellulaire';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Écosystèmes","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Producteurs, consommateurs, flux d''énergie, cycles.","exercices":[{"number":1,"title_fr":"Structure d''un écosystème","points":5,"preamble_fr":"Définitions.","questions":[{"number":1,"stem_fr":"Biocénose, biotope, écosystème.","points":3,"solution":{"steps":[{"text_fr":"**Biocénose** : ensemble des êtres vivants d''un milieu (faune + flore + microbes)."},{"text_fr":"**Biotope** : milieu physique (sol, climat, eau, lumière)."},{"text_fr":"**Écosystème** = biocénose + biotope + leurs interactions."}],"final_answer_fr":"vivant + milieu + interactions"}},{"number":2,"stem_fr":"Niveaux trophiques.","points":2,"solution":{"steps":[{"text_fr":"**Producteurs (autotrophes)** : plantes vertes, algues, cyanobactéries."},{"text_fr":"**Consommateurs primaires** : herbivores. **Secondaires** : carnivores qui mangent les herbivores. **Tertiaires** : super-prédateurs."},{"text_fr":"**Décomposeurs** : champignons, bactéries du sol — recyclent la matière morte."}],"final_answer_fr":"producteurs, conso, décomposeurs"}}]},{"number":2,"title_fr":"Flux d''énergie","points":5,"preamble_fr":"Règle des 10%.","questions":[{"number":1,"stem_fr":"Que devient l''énergie à chaque niveau trophique ?","points":3,"solution":{"steps":[{"text_fr":"Sur 100% d''énergie ingérée par un niveau, ~10% est transférée au niveau suivant."},{"text_fr":"Le reste (~90%) est perdu : respiration (chaleur dissipée), excréments, parties non consommées."},{"text_fr":"Conséquence : **pyramide d''énergie** étroite au sommet. Peu d''énergie disponible pour les super-prédateurs."}],"final_answer_fr":"10% transféré, 90% perdu"}},{"number":2,"stem_fr":"Pourquoi peu de niveaux trophiques (4-5 max) ?","points":2,"solution":{"steps":[{"text_fr":"À chaque niveau, division par 10. Au-delà de 4-5 niveaux, énergie disponible insuffisante pour maintenir une population."},{"text_fr":"Plus de lions que de léopards (carnivores), mais beaucoup plus de gazelles (herbivores)."}],"final_answer_fr":"énergie épuisée"}}]},{"number":3,"title_fr":"Cycle du carbone","points":5,"preamble_fr":"Carbone biologique et géologique.","questions":[{"number":1,"stem_fr":"Réservoirs principaux.","points":3,"solution":{"steps":[{"text_fr":"Atmosphère (CO₂, peu mais accessible)."},{"text_fr":"Océans (CO₂ dissous, énorme réservoir)."},{"text_fr":"Biosphère (matière organique vivante)."},{"text_fr":"Sols (matière organique morte, humus)."},{"text_fr":"Combustibles fossiles (charbon, pétrole — C piégé depuis des millions d''années)."}],"final_answer_fr":"5 réservoirs principaux"}},{"number":2,"stem_fr":"Flux principaux.","points":2,"solution":{"steps":[{"text_fr":"**Photosynthèse** : atmosphère → biosphère. **Respiration et combustion** : biosphère → atmosphère."},{"text_fr":"**Échanges air-mer** : CO₂ atmosphérique se dissout dans les océans (~30% du CO₂ anthropique absorbé)."},{"text_fr":"**Stockage géologique** : à très long terme, biosphère → fossiles."}],"final_answer_fr":"photosynthèse, respiration, dissolution"}}]},{"number":4,"title_fr":"Perturbations anthropiques","points":5,"preamble_fr":"Impact humain.","questions":[{"number":1,"stem_fr":"Effet de serre : mécanisme.","points":3,"solution":{"steps":[{"text_fr":"Le CO₂ et autres gaz à effet de serre (CH₄, N₂O, vapeur d''eau) laissent passer la lumière visible mais absorbent l''infrarouge réémis par la surface."},{"text_fr":"Effet de serre **naturel** : indispensable à la vie (sans lui, T moyenne = -18°C au lieu de +15°C)."},{"text_fr":"Effet de serre **anthropique** : excès de CO₂ dû à la combustion fossile → réchauffement global."}],"final_answer_fr":"piégeage IR"}},{"number":2,"stem_fr":"Conséquences observées.","points":2,"solution":{"steps":[{"text_fr":"Hausse de T globale (~+1,1°C depuis 1880), événements météo extrêmes."},{"text_fr":"Fonte des glaces, hausse niveau marin (+20 cm en 100 ans)."},{"text_fr":"Acidification des océans (CO₂ + H₂O → H₂CO₃ → H⁺ + HCO₃⁻)."},{"text_fr":"Perte de biodiversité (changement de niches, extinctions)."}],"final_answer_fr":"T, glaces, océans, biodiversité"}}]}]}'::jsonb WHERE code = 'svt_ecosystemes';

COMMIT;
